end

local ICON = {}
for name, b64 in pairs(ASSET_DATA) do
	local raw = crypt.base64decode(b64)
	local path = DIR_ASSETS .. "/" .. name .. "_" .. #raw .. ".png" -- size in the name busts the asset cache
	if not isfile(path) then writefile(path, raw) end
	ICON[name] = getcustomasset(path)
end

