---------------------------------------------------------------- springs & frame loop

-- Critically damped spring, implicit integration: no overshoot, stable at any fps.
-- Snaps exactly onto the target once settled so nothing drifts by sub-pixels at rest.
local Spring = {}
Spring.__index = Spring
function Spring:step(dt)
	local x, t = self.x, self.t
	if x == t and self.v == 0 then return x end
	local w = self.w
	local f = 1 + 2 * dt * w
	local hoo = dt * w * w
	local hhoo = dt * hoo
	local inv = 1 / (f + hhoo)
	self.x = (f * x + dt * self.v + hhoo * t) * inv
	self.v = (self.v + hoo * (t - x)) * inv
	if math.abs(t - self.x) < self.eps and math.abs(self.v) < self.eps * 20 then
		self.x, self.v = t, 0
	end
	return self.x
end
function Spring:snap(x)
	self.x, self.t, self.v = x, x, 0
end

local springs, frameFns = {}, {}
local function spring(x, speed, eps)
	local s = setmetatable({ x = x, v = 0, t = x, w = speed, eps = eps or 1e-3 }, Spring)
	springs[s] = true
	return s
end
-- fn(dt) runs every frame; returning true unregisters it.
C.always = setmetatable({}, { __mode = "k" })
local function onFrame(fn, always)
	frameFns[fn] = true
	if always then C.always[fn] = true end
end

---------------------------------------------------------------- instance helpers

local conns = {}
local function on(sig, fn)
	local c = sig:Connect(fn)
	conns[#conns + 1] = c
	return c
end

local function new(class, props, children)
	local o = Instance.new(class)
	for k, v in pairs(props) do
		if k ~= "Parent" then o[k] = v end
	end
	for _, c in ipairs(children or {}) do c.Parent = o end
	if props.Parent then o.Parent = props.Parent end
	return o
end
local function corner(r) return new("UICorner", { CornerRadius = UDim.new(0, r) }) end
local function stroke(color, parent)
	return new("UIStroke", { Color = color, Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = parent })
end
local function round(x) return math.floor(x + 0.5) end
local function even(x) return 2 * math.floor(x / 2 + 0.5) end
local function clamp01(x) return math.clamp(x, 0, 1) end
local function smooth(u) return u * u * (3 - 2 * u) end
local function textWidth(text, size, font)
	return TextService:GetTextSize(text, size, font, Vector2.new(1e4, 100)).X
end
local function inside(g, p)
	local a, s = g.AbsolutePosition, g.AbsoluteSize
	return p.X >= a.X and p.Y >= a.Y and p.X <= a.X + s.X and p.Y <= a.Y + s.Y
end
local function shiftDown()
	return UIS:IsKeyDown(Enum.KeyCode.LeftShift) or UIS:IsKeyDown(Enum.KeyCode.RightShift)
end
local function label(props)
	props.BackgroundTransparency = 1
	props.Font = props.Font or Enum.Font.BuilderSans
	props.TextSize = props.TextSize or 12
	props.TextColor3 = props.TextColor3 or C.text
	props.TextXAlignment = props.TextXAlignment or Enum.TextXAlignment.Left
	return new("TextLabel", props)
end
local function icon(img, size, props)
	props = props or {}
	props.Image = img
	props.BackgroundTransparency = 1
	props.Size = props.Size or UDim2.fromOffset(size, size)
	props.AnchorPoint = props.AnchorPoint or Vector2.new(0.5, 0.5)
	return new("ImageLabel", props)
end
local function button(props, children)
	props.Text = ""
	props.AutoButtonColor = false
	props.BorderSizePixel = 0
	if props.BackgroundColor3 == nil then
		props.BackgroundColor3 = Color3.new(1, 1, 1)
		props.BackgroundTransparency = props.BackgroundTransparency or 1
	end
	return new("TextButton", props, children)
end

-- Accent color follows the "Menu color" setting live.
local accent = DEFAULT_ACCENT
local accentBinds = {}
local function bindAccent(inst, fn)
	accentBinds[#accentBinds + 1] = { inst, fn }
	fn(accent)
end
local function setAccent(c)
	accent = c
	for i = #accentBinds, 1, -1 do
		local b = accentBinds[i]
		if b[1].Parent then b[2](c) else table.remove(accentBinds, i) end
	end
end

-- Hover/press springs; hovered controls also block window dragging.
local hovered, pressSprings = {}, {}
local function hoverable(g)
	local st = { hover = spring(0, 30), press = spring(0, 42) }
	pressSprings[st.press] = true
	on(g.MouseEnter, function() st.hover.t = 1; hovered[g] = true end)
	on(g.MouseLeave, function() st.hover.t = 0; st.press.t = 0; hovered[g] = nil end)
	if g:IsA("GuiButton") then
		on(g.MouseButton1Down, function() st.press.t = 1 end)
	end
	on(g.Destroying, function()
		hovered[g] = nil
		springs[st.hover], springs[st.press], pressSprings[st.press] = nil, nil, nil
	end)
	return st
end

-- Mouse wheel targets: one step per notch, Shift for ten.
local wheelTargets, hoveredWheel = {}, nil
local function onWheel(g, fn)
	wheelTargets[g] = fn
	on(g.MouseEnter, function() hoveredWheel = g end)
	on(g.MouseLeave, function() if hoveredWheel == g then hoveredWheel = nil end end)
	on(g.Destroying, function()
		wheelTargets[g] = nil
		if hoveredWheel == g then hoveredWheel = nil end
	end)
end

