-- A small card in the top-right corner while the menu builds; each step yields a frame so it animates.
local inject
do
	local TweenService = game:GetService("TweenService")
	local TOTAL = 8
	local step = 0
	local tg = new("ScreenGui", { Name = tostring(math.random(1e8, 9e8)), IgnoreGuiInset = true, ResetOnSpawn = false, DisplayOrder = 10002 })
	if syn and syn.protect_gui then pcall(syn.protect_gui, tg) end
	local okH, h = pcall(function() return gethui and gethui() end)
	tg.Parent = (okH and h) or CoreGui
	local card = new("CanvasGroup", {
		BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 14, 0, 16),
		Size = UDim2.fromOffset(262, 58), GroupTransparency = 1, Parent = tg,
	})
	local bg = new("Frame", { BackgroundColor3 = C.popup, BackgroundTransparency = 0.04, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), Parent = card }, { corner(8) })
	stroke(C.popupStroke, bg)
	local logo = new("Frame", { BackgroundColor3 = DEFAULT_ACCENT, BorderSizePixel = 0, Position = UDim2.fromOffset(11, 11), Size = UDim2.fromOffset(36, 36), Parent = bg }, { corner(8) })
	icon(ICON.crosshair, 19, { Position = UDim2.fromScale(0.5, 0.5), ImageColor3 = Color3.new(1, 1, 1), Parent = logo })
	local title = label({ Text = "Injecting", Font = Enum.Font.BuilderSansMedium, TextSize = 13, TextColor3 = C.hi, Position = UDim2.fromOffset(58, 11), Size = UDim2.new(1, -66, 0, 16), Parent = bg })
	local sub = label({ Text = "", TextSize = 12, TextColor3 = C.dim, Position = UDim2.fromOffset(58, 30), Size = UDim2.new(1, -66, 0, 16), Parent = bg })
	local bar = new("Frame", { BackgroundColor3 = DEFAULT_ACCENT, BorderSizePixel = 0, AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 0, 1, 0), Size = UDim2.new(0, 0, 0, 2), Parent = bg })
	local ease = TweenInfo.new(0.35, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
	TweenService:Create(card, ease, { GroupTransparency = 0, Position = UDim2.new(1, -16, 0, 16) }):Play()
	inject = function(done)
		step = done and TOTAL or math.min(step + 1, TOTAL)
		sub.Text = done and string.format("Ready [%d/%d]", TOTAL, TOTAL) or string.format("Initialization in progress [%d/%d]...", step, TOTAL)
		TweenService:Create(bar, TweenInfo.new(0.25, Enum.EasingStyle.Quad), { Size = UDim2.new(step / TOTAL, 0, 0, 2) }):Play()
		if done then
			title.Text = "Injected"
			task.delay(1.4, function()
				local out = TweenService:Create(card, ease, { GroupTransparency = 1, Position = UDim2.new(1, 14, 0, 16) })
				out.Completed:Connect(function() tg:Destroy() end)
				out:Play()
			end)
		else
			task.wait(0.06)
		end
	end
end

inject()

