-- Frosted sidebar: a near-invisible Glass part right in front of the camera, covering the sidebar,
-- plus a near-field DepthOfField blurs the world seen through it (glass needs graphics level 8+).
local Lighting = game:GetService("Lighting")
local blurDof = new("DepthOfFieldEffect", { FarIntensity = 0, FocusDistance = 51.6, InFocusRadius = 50, NearIntensity = 1, Enabled = false, Parent = Lighting })
local glassMesh = new("SpecialMesh", { MeshType = Enum.MeshType.Brick, Offset = Vector3.new(0, 0, -1e-6) })
local glass = new("Part", {
	Material = Enum.Material.Glass, Color = Color3.new(0, 0, 0), Transparency = 1,
	Anchored = true, CanCollide = false, CanQuery = false, CanTouch = false, CastShadow = false,
	Size = Vector3.new(1, 1, 0.001), Parent = workspace.CurrentCamera,
}, { glassMesh })
local mutedDof = {} -- the game's own DepthOfField effects, off while ours runs
local function muteOtherDof()
	local cam = workspace.CurrentCamera
	for _, parent in ipairs({ Lighting, cam }) do
		for _, e in ipairs(parent and parent:GetChildren() or {}) do
			if e:IsA("DepthOfFieldEffect") and e ~= blurDof and e.Enabled then
				mutedDof[e] = true
				e.Enabled = false
			end
		end
	end
end
local function setBlur(k) -- k: how much of the window is shown, 0..1
	-- glass + DoF need graphics 8+; below that the sidebar turns solid instead of see-through
	local okQ, q = pcall(function() return UserSettings():GetService("UserGameSettings").SavedQualityLevel end)
	local weak = okQ and q ~= Enum.SavedQualitySetting.Automatic and q.Value < 8
	sideBg.BackgroundTransparency = weak and 0.02 or 0.13
	-- the game wipes the camera / Lighting on map loads and respawns: whatever of ours got destroyed
	-- is rebuilt right here, every frame, so the blur can never die for good
	if not pcall(function() if blurDof.Parent ~= Lighting then blurDof.Parent = Lighting end end) then
		blurDof = new("DepthOfFieldEffect", { FarIntensity = 0, FocusDistance = 51.6, InFocusRadius = 50, NearIntensity = 1, Enabled = false, Parent = Lighting })
	end
	if blurDof.FocusDistance ~= 51.6 or blurDof.InFocusRadius ~= 50 or blurDof.FarIntensity ~= 0 then
		blurDof.FarIntensity, blurDof.FocusDistance, blurDof.InFocusRadius = 0, 51.6, 50
	end
	local camNow = workspace.CurrentCamera
	if camNow and not pcall(function()
		if glass.Parent ~= camNow then glass.Parent = camNow end
		if glassMesh.Parent ~= glass then glassMesh.Parent = glass end
	end) then
		glassMesh = new("SpecialMesh", { MeshType = Enum.MeshType.Brick, Offset = Vector3.new(0, 0, -1e-6) })
		glass = new("Part", {
			Material = Enum.Material.Glass, Color = Color3.new(0, 0, 0), Transparency = 1,
			Anchored = true, CanCollide = false, CanQuery = false, CanTouch = false, CastShadow = false,
			Size = Vector3.new(1, 1, 0.001), Parent = camNow,
		}, { glassMesh })
	end
	local enable = k > 0.01 and not weak
	if not enable and next(mutedDof) then
		for e in pairs(mutedDof) do
			if e.Parent then e.Enabled = true end
		end
		table.clear(mutedDof)
	end
	if blurDof.Parent ~= Lighting then blurDof.Parent = Lighting end
	if blurDof.Enabled ~= enable then blurDof.Enabled = enable end
	blurDof.NearIntensity = enable and k or 0
	glass.Transparency = enable and 0.98 or 1
	if enable then muteOtherDof() end
end
-- Runs right after the camera script each frame, so the glass never trails the camera.
local GLASS_STEP = "FischMenuGlass" .. gui.Name
RunService:BindToRenderStep(GLASS_STEP, Enum.RenderPriority.Last.Value + 5000, function() pcall(function()
	local GLASS_DEPTH = 0.2
	if not blurDof.Enabled then return end
	muteOtherDof() -- games re-enable their own DoF (scopes, menus); keep ours the only one
	local cam = workspace.CurrentCamera
	if not cam then return end
	if glass.Parent ~= cam then glass.Parent = cam end
	-- the sidebar normally; the whole window while a page overlay (Ambience) is frosted
	local src = window:GetAttribute("FrostAll") and window or sideBg
	local o = probe.AbsolutePosition
	local p0 = src.AbsolutePosition - o + Vector2.new(1, 1)
	local p1 = p0 + src.AbsoluteSize - Vector2.new(2, 2)
	local look = cam.CFrame.LookVector
	local function at(x, y)
		local ray = cam:ViewportPointToRay(x, y)
		local d = ray.Direction.Unit
		return ray.Origin + d * (GLASS_DEPTH / math.max(d:Dot(look), 1e-3))
	end
	local tl, tr, bl = at(p0.X, p0.Y), at(p1.X, p0.Y), at(p0.X, p1.Y)
	local right, down = tr - tl, bl - tl
	if right.Magnitude < 1e-6 or down.Magnitude < 1e-6 then return end
	glass.CFrame = CFrame.fromMatrix(tl + right / 2 + down / 2, right.Unit, -down.Unit)
	glassMesh.Scale = Vector3.new(right.Magnitude, down.Magnitude, 0)
end) end)

