---------------------------------------------------------------- popups

local popupStack = {}
local popupZ = 0

local Popup = {}
Popup.__index = Popup
function Popup.new(width, height, transparency)
	local p = setmetatable({}, Popup)
	p.w = width
	p.h = spring(height, 30, 0.01)
	p.alpha = spring(1, 30, 1e-4)
	p.pos = Vector2.zero
	p.dir = 1 -- +1 drops down, -1 rises up
	p.open = false
	p.group = new("CanvasGroup", {
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Visible = false,
		GroupTransparency = 1,
		Parent = overlay,
	})
	shadow(p.group, PP, 0.25)
	p.inner = new("Frame", {
		BackgroundColor3 = C.popup,
		BackgroundTransparency = transparency or 0,
		BorderSizePixel = 0,
		Active = true,
		ClipsDescendants = true,
		Position = UDim2.fromOffset(PP, PP),
		Size = UDim2.new(1, -2 * PP, 1, -2 * PP),
		Parent = p.group,
	}, { corner(8) })
	stroke(C.popupStroke, p.inner)
	onFrame(function()
		local h = round(p.h.x)
		local y = p.bottom and (p.bottom - h) or p.pos.Y
		local slide = -p.dir * 6 * p.alpha.x
		p.group.Size = UDim2.fromOffset(p.w + 2 * PP, h + 2 * PP)
		p.group.Position = UDim2.fromOffset(round(p.pos.X) - PP, round(y + slide) - PP)
		p.group.GroupTransparency = p.alpha.x
		p.group.Visible = p.open or p.alpha.x < 0.995
	end)
	return p
end
function Popup:show(anchor)
	if self.open then
		self.alpha:snap(0.6) -- re-pop when reopened somewhere else
	else
		self.open = true
		popupStack[#popupStack + 1] = self
	end
	self.alpha.t = 0
	self.anchor = anchor
	popupZ += 1
	self.group.ZIndex = popupZ
end
function Popup:hide()
	local idx = table.find(popupStack, self)
	if not idx then return end
	for i = #popupStack, idx, -1 do
		local q = table.remove(popupStack, i)
		q.open = false
		q.alpha.t = 1
		if q.onHide then q.onHide() end
	end
end
function Popup:place(x, y, h)
	local ws = winSize()
	self.pos = Vector2.new(math.clamp(x, 6, ws.X - self.w - 6), math.clamp(y, 6, math.max(6, ws.Y - h - 6)))
end
-- Below the anchor (or above when there's no room), aligned to its left or right edge.
function Popup:placeAt(anchor, h, alignRight)
	local r = relPos(anchor)
	local x = alignRight and (r.X + anchor.AbsoluteSize.X / C.S() - self.w) or r.X
	local y = r.Y + anchor.AbsoluteSize.Y / C.S() + 6
	self.dir = 1
	if y + h > winSize().Y - 6 then
		y = r.Y - 6 - h
		self.dir = -1
	end
	self:place(x, y, h)
end

local function hideAllPopups()
	if popupStack[1] then popupStack[1]:hide() end
end
local function popupAt(pt)
	for i = #popupStack, 1, -1 do
		if inside(popupStack[i].inner, pt) then return popupStack[i] end
	end
end
local function closePopupsOutside(pt)
	for i = #popupStack, 1, -1 do
		local p = popupStack[i]
		if inside(p.inner, pt) or (p.anchor and p.anchor.Parent and inside(p.anchor, pt)) then break end
		p:hide()
	end
end

