local toastA = spring(0, 26, 1e-4)
local toastUntil = 0
local function toast(msg)
	toastLabel.Text = msg
	toastA.t = 1
	toastUntil = os.clock() + 1.6
end
onFrame(function()
	if os.clock() > toastUntil then toastA.t = 0 end
	local a = toastA.x
	toastFrame.Visible = a > 0.002
	toastFrame.BackgroundTransparency = 1 - a
	toastLabel.TextTransparency = 1 - a
	toastStroke.Transparency = 1 - a
	toastFrame.Position = UDim2.new(0.5, round(SIDE_W / 2), 1, round(-14 + (1 - a) * 6))
end)

---------------------------------------------------------------- context menu (shared)

local ctx = Popup.new(176, 40)
local ctxRows = {}
-- items: { icon=, swatch=Color3, text=, danger=, disabled=, fn= }
local function openContext(items, at, anchor)
	for _, r in ipairs(ctxRows) do r:Destroy() end
	table.clear(ctxRows)
	for i, it in ipairs(items) do
		local b = button({
			Position = UDim2.fromOffset(4, 4 + (i - 1) * 28),
			Size = UDim2.new(1, -8, 0, 28),
			Parent = ctx.inner,
		}, { corner(5) })
		ctxRows[i] = b
		local base = it.danger and C.danger or C.text
		local ic
		if it.swatch then
			ic = new("Frame", {
				BackgroundColor3 = it.swatch,
				BorderSizePixel = 0,
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromOffset(16, 14),
				Size = UDim2.fromOffset(11, 11),
				Parent = b,
			}, { corner(3) })
		elseif it.icon then
			ic = icon(it.icon, 14, { Position = UDim2.fromOffset(16, 14), ImageColor3 = base, Parent = b })
		end
		local t = label({ Text = it.text, Position = UDim2.fromOffset(31, 0), Size = UDim2.new(1, -36, 1, 0), Parent = b })
		local st = hoverable(b)
		onFrame(function()
			if not b.Parent then return true end
			local hv = it.disabled and 0 or st.hover.x
			b.BackgroundTransparency = 1 - 0.05 * hv
			local col = it.disabled and C.faint or base:Lerp(it.danger and rgb(255, 130, 130) or C.hi, hv)
			t.TextColor3 = col
			if ic and ic:IsA("ImageLabel") then ic.ImageColor3 = col end
			if ic and it.swatch then ic.BackgroundTransparency = it.disabled and 0.7 or 0 end
		end)
		on(b.Activated, function()
			if it.disabled then return end
			ctx:hide()
			it.fn()
		end)
	end
	local w = 0
	for _, it in ipairs(items) do w = math.max(w, textWidth(it.text, 12, Enum.Font.BuilderSans)) end
	ctx.w = math.max(110, round(31 + w + 16))
	local h = 8 + #items * 28
	ctx.h:snap(h)
	ctx:place(at.X, at.Y, h)
	ctx:show(anchor)
end
-- Context menu at the cursor.
local function contextAtMouse(items, anchor)
	local m = (mouseAbs() - overlay.AbsolutePosition) / C.S()
	openContext(items, Vector2.new(m.X + 4, m.Y + 4), anchor)
end

---------------------------------------------------------------- values

local function keyName(k)
	local NAMES = {
		MouseButton1 = "Mouse 1", MouseButton2 = "Mouse 2", MouseButton3 = "Mouse 3",
		LeftShift = "L Shift", RightShift = "R Shift", LeftControl = "L Ctrl", RightControl = "R Ctrl",
		LeftAlt = "L Alt", RightAlt = "R Alt", LeftSuper = "L Win", RightSuper = "R Win",
		Return = "Enter", Escape = "Esc", CapsLock = "Caps", PageUp = "Page Up", PageDown = "Page Down",
		Zero = "0", One = "1", Two = "2", Three = "3", Four = "4", Five = "5", Six = "6", Seven = "7", Eight = "8", Nine = "9",
		Minus = "-", Equals = "=", LeftBracket = "[", RightBracket = "]", BackSlash = "\\", Semicolon = ";",
		Quote = "'", Comma = ",", Period = ".", Slash = "/", Backquote = "`", Tilde = "~",
		KeypadPlus = "Num +", KeypadMinus = "Num -", KeypadMultiply = "Num *", KeypadDivide = "Num /",
		KeypadPeriod = "Num .", KeypadEnter = "Num Enter", KeypadEquals = "Num =",
	}
	local n = k.name
	if NAMES[n] then return NAMES[n] end
	local kp = n:match("^Keypad(%a+)$")
	if kp then return "Num " .. (NAMES[kp] or kp) end
	return (n:gsub("(%l)(%u)", "%1 %2"))
end

local function validKey(k)
	if type(k) ~= "table" or type(k.name) ~= "string" then return false end
	if k.kind == "Mouse" then return k.name == "MouseButton1" or k.name == "MouseButton2" or k.name == "MouseButton3" end
	return k.kind == "Key" and (pcall(function() return Enum.KeyCode[k.name] end))
end

local menuKey = { kind = "Key", name = "Insert" }

local function matchesKey(input, k)
	if k.kind == "Mouse" then return input.UserInputType.Name == k.name end
	return input.KeyCode ~= Enum.KeyCode.Unknown and input.KeyCode.Name == k.name
end

-- Color value: target HSVA plus display springs everything visual reads from.
local ColorValue = {}
ColorValue.__index = ColorValue
local function colorValue(c, a)
	local h, s, v = c:ToHSV()
	return setmetatable({
		h = h, s = s, v = v, a = a, def = { c, a },
		dh = spring(h, 30, 1e-4), ds = spring(s, 30, 1e-4), dv = spring(v, 30, 1e-4), da = spring(a, 30, 1e-4),
	}, ColorValue)
end
function ColorValue:set(h, s, v, a, instant)
	self.h, self.s, self.v, self.a = clamp01(h), clamp01(s), clamp01(v), clamp01(a)
	self.dh.t, self.ds.t, self.dv.t, self.da.t = self.h, self.s, self.v, self.a
	if instant then
		self.dh:snap(self.h); self.ds:snap(self.s); self.dv:snap(self.v); self.da:snap(self.a)
	end
end
function ColorValue:setRGB(c, a, instant)
	local h, s, v = c:ToHSV()
	if v < 1e-4 then h, s = self.h, self.s
	elseif s < 1e-4 then h = self.h end -- greys have no hue: keep the old one
	self:set(h, s, v, a or self.a, instant)
end
function ColorValue:rgb() return Color3.fromHSV(self.h, self.s, self.v) end
function ColorValue:display() return Color3.fromHSV(self.dh.x, self.ds.x, self.dv.x) end

local function to255(c) return round(c.R * 255), round(c.G * 255), round(c.B * 255) end
local function hex6(c) return string.format("%02X%02X%02X", to255(c)) end
local function hex8(cv) return hex6(cv:rgb()) .. string.format("%02X", round(cv.a * 255)) end
local function parseHex(str)
	str = str:gsub("[#%s]", "")
	if #str == 3 then str = str:gsub(".", "%0%0") end
	if (#str ~= 6 and #str ~= 8) or str:find("[^%x]") then return nil end
	local c = Color3.fromRGB(tonumber(str:sub(1, 2), 16), tonumber(str:sub(3, 4), 16), tonumber(str:sub(5, 6), 16))
	local a = #str == 8 and tonumber(str:sub(7, 8), 16) / 255 or nil
	return c, a
end

local menuColor = colorValue(DEFAULT_ACCENT, 1)
local colorClip -- { h, s, v, a } copied from any color widget

---------------------------------------------------------------- config storage

-- Every saved setting registers here: id -> { save = fn() -> json value, load = fn(value) }.
local options = {
	menuKey = {
		save = function() return { kind = menuKey.kind, name = menuKey.name } end,
		load = function(t) if validKey(t) then menuKey = { kind = t.kind, name = t.name } end end,
	},
	menuColor = {
		save = function() return hex8(menuColor) end,
		load = function(t)
			local c, a = parseHex(tostring(t))
			if c then menuColor:setRGB(c, a or 1) end
		end,
	},
}

local function cfgPath(dir, name) return dir .. "/" .. name .. ".json" end
local function listNames(dir)
	local out = {}
	local ok, files = pcall(listfiles, dir)
	for _, f in ipairs(ok and files or {}) do
		local n = f:match("([^/\\]+)%.json$")
		if n then out[#out + 1] = n end
	end
	return out
end
local function uniqueName(dir, base)
	if not isfile(cfgPath(dir, base)) then return base end
	local i = 2
	while isfile(cfgPath(dir, base .. " " .. i)) do i += 1 end
	return base .. " " .. i
end
local function sanitize(n)
	n = n:gsub('[\\/:*?"<>|%c]', ""):gsub("^%s+", ""):gsub("%s+$", "")
	return n:sub(1, 40)
end

local selected -- active config name or nil
local function saveState()
	pcall(writefile, STATE_FILE, HttpService:JSONEncode({ config = selected or "" }))
end
local function serialize()
	local t = {}
	for id, o in pairs(options) do t[id] = o.save() end
	return HttpService:JSONEncode(t)
end
local function applyConfig(json)
	local ok, t = pcall(HttpService.JSONDecode, HttpService, json)
	if not ok or type(t) ~= "table" then return false end
	for id, o in pairs(options) do
		if t[id] ~= nil then pcall(o.load, t[id]) end
	end
	return true
end

local Configs = {}
local refreshConfigs = function() end -- replaced by the config UI
function Configs.save(name)
	writefile(cfgPath(DIR_CFG, name), serialize())
end
function Configs.load(name)
	local ok, data = pcall(readfile, cfgPath(DIR_CFG, name))
	if ok and applyConfig(data) then
		selected = name
		saveState()
	end
	refreshConfigs()
end
function Configs.create(raw)
	local name = sanitize(raw)
	if name == "" then return end
	name = uniqueName(DIR_CFG, name)
	Configs.save(name)
	selected = name
	saveState()
	refreshConfigs()
end
function Configs.duplicate(name)
	local ok, data = pcall(readfile, cfgPath(DIR_CFG, name))
	if not ok then return end
	writefile(cfgPath(DIR_CFG, uniqueName(DIR_CFG, name .. " copy")), data)
	refreshConfigs()
end
function Configs.share(name)
	local ok, data = pcall(readfile, cfgPath(DIR_CFG, name))
	if ok and setclipboard then
		setclipboard(data)
		toast("Config copied to clipboard")
	end
end
function Configs.delete(name)
	local ok, data = pcall(readfile, cfgPath(DIR_CFG, name))
	if not ok then return end
	writefile(cfgPath(DIR_TRASH, uniqueName(DIR_TRASH, name)), data)
	delfile(cfgPath(DIR_CFG, name))
	if selected == name then
		selected = nil
		saveState()
	end
	refreshConfigs()
end
function Configs.restore(name)
	local ok, data = pcall(readfile, cfgPath(DIR_TRASH, name))
	if not ok then return end
	writefile(cfgPath(DIR_CFG, uniqueName(DIR_CFG, name)), data)
	delfile(cfgPath(DIR_TRASH, name))
	refreshConfigs()
end
function Configs.purge(name)
	pcall(delfile, cfgPath(DIR_TRASH, name))
	refreshConfigs()
end
function Configs.rename(old, raw)
	local name = sanitize(raw)
	local ok, data = pcall(readfile, cfgPath(DIR_CFG, old))
	if name == "" or name == old or not ok then
		refreshConfigs()
		return
	end
	-- a case-only rename hits the same file on Windows, so don't treat it as taken
	if name:lower() ~= old:lower() then name = uniqueName(DIR_CFG, name) end
	delfile(cfgPath(DIR_CFG, old))
	writefile(cfgPath(DIR_CFG, name), data)
	if selected == old then
		selected = name
		saveState()
	end
	refreshConfigs()
end

inject()

---------------------------------------------------------------- tabs

local tabs, pages = {}, {}
local current
local tabsBottom = 0
local indY = spring(0, 26, 0.01)
local pageY = spring(0, 11, 0.01)
C.pageFade = spring(0, 10, 1e-3)

local snapHighlight = false
local function selectTab(tab, instant)
	if current == tab then return end
	if current then
		current.active.t = 0
		current.page.Visible = false
	end
	current = tab
	tab.active.t = 1
	tab.page.Visible = true
	if instant then
		snapHighlight = true
		tab.active:snap(1)
	else
		pageY:snap(4)
		pageY.t = 0
		C.pageFade:snap(1)
		C.pageFade.t = 0
	end
end

do
	local highlight = new("Frame", {
		BackgroundColor3 = Color3.new(1, 1, 1),
		BackgroundTransparency = 0.93,
		BorderSizePixel = 0,
		Size = UDim2.new(1, -16, 0, TAB_H),
		Parent = sidebar,
	}, { corner(6) })

	local function makePage(name)
		return new("ScrollingFrame", {
			Name = name,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Size = UDim2.fromScale(1, 1),
			CanvasSize = UDim2.new(),
			AutomaticCanvasSize = Enum.AutomaticSize.Y,
			ScrollBarThickness = 2,
			ScrollBarImageColor3 = C.faint,
			ScrollingDirection = Enum.ScrollingDirection.Y,
			Visible = false,
			Parent = pageHost,
		}, { new("UIPadding", { PaddingTop = UDim.new(0, 2), PaddingBottom = UDim.new(0, 16) }) })
	end

	local function tabButton(name, iconName, parent, x)
		local btn = button({ Position = UDim2.fromOffset(x, 0), Size = UDim2.new(1, -x - 8, 0, TAB_H), ZIndex = 2, Parent = parent }, { corner(6) })
		local ic = icon(ICON[iconName], 15, { Position = UDim2.fromOffset(17, TAB_H / 2), ImageColor3 = C.tabIdle, ZIndex = 2, Parent = btn })
		local lbl = label({
			Text = name, Font = Enum.Font.BuilderSansMedium, TextSize = 13, TextColor3 = C.tabIdle,
			Position = UDim2.fromOffset(34, 0), Size = UDim2.new(1, -40, 1, 0), ZIndex = 2, Parent = btn,
		})
		return btn, ic, lbl
	end

	local function addTab(def, parent, x, indent)
		local btn, ic, lbl = tabButton(def.tab, def.icon, parent, x)
		local tab = {
			name = def.tab, y = 0, indent = indent, btn = btn, icon = ic, label = lbl,
			page = makePage(def.tab), st = hoverable(btn), active = spring(0, 22), fade = 1,
		}
		tabs[#tabs + 1] = tab
		pages[def.tab] = tab.page
		on(btn.Activated, function() selectTab(tab) end)
		return tab
	end

	local items = {}
	for i, item in ipairs(NAV) do
		if item.section then
			items[#items + 1] = {
				kind = "section", gap = i > 1,
				inst = label({
					Text = item.section:upper(), Font = Enum.Font.BuilderSansBold, TextSize = 10, TextColor3 = C.section,
					Size = UDim2.new(1, -32, 0, 22), Parent = sidebar,
				}),
			}
		elseif item.group then
			-- A group header can't be opened itself; its sub-tabs slide out on hover or click.
			local btn, ic, lbl = tabButton(item.group, item.icon, sidebar, 8)
			local box = new("Frame", { BackgroundTransparency = 1, ClipsDescendants = true, Size = UDim2.new(1, 0, 0, 0), ZIndex = 2, Parent = sidebar })
			local g = { kind = "group", btn = btn, icon = ic, label = lbl, box = box, st = hoverable(btn), open = spring(0, 22, 1e-3), children = {}, pinned = false, lastHover = 0 }
			on(btn.Activated, function() g.pinned = not g.pinned end)
			for ci, c in ipairs(item.children) do
				local tab = addTab(c, box, 20, 12)
				tab.btn.Position = UDim2.fromOffset(20, (ci - 1) * (TAB_H + 2))
				tab.group = g
				g.children[#g.children + 1] = tab
			end
			items[#items + 1] = g
		else
			local tab = addTab(item, sidebar, 8, 0)
			items[#items + 1] = { kind = "tab", tab = tab }
		end
	end

	onFrame(function()
		local y = HEADER_H + 10
		for _, it in ipairs(items) do
			if it.kind == "section" then
				if it.gap then y += 10 end
				it.inst.Position = UDim2.fromOffset(16, y)
				y += 22
			elseif it.kind == "tab" then
				it.tab.y = y
				it.tab.btn.Position = UDim2.fromOffset(8, y)
				y += TAB_H + 2
			else
				local hoverAny, childActive = it.st.hover.t == 1, false
				for _, c in ipairs(it.children) do
					if c.st.hover.t == 1 then hoverAny = true end
					if c == current then childActive = true end
				end
				if hoverAny then it.lastHover = os.clock() end
				-- short grace so moving from the header down to a sub-tab doesn't fold it
				it.open.t = (it.pinned or childActive or os.clock() - it.lastHover < 0.2) and 1 or 0
				it.btn.Position = UDim2.fromOffset(8, y)
				y += TAB_H + 2
				local o = it.open.x
				local full = #it.children * (TAB_H + 2)
				it.box.Position = UDim2.fromOffset(0, y)
				it.box.Size = UDim2.new(1, 0, 0, round(full * o))
				it.box.Visible = o > 0.01
				for ci, c in ipairs(it.children) do
					c.y = y + (ci - 1) * (TAB_H + 2)
					c.fade = o
				end
				y += full * o
				local hv = it.st.hover.x
				it.label.TextColor3 = C.tabIdle:Lerp(C.hi, math.max(hv * 0.85, o * 0.35))
				it.icon.ImageColor3 = C.tabIdle:Lerp(C.hi, math.max(hv * 0.85, o * 0.35))
				it.btn.BackgroundTransparency = 1 - 0.03 * hv
			end
		end
		tabsBottom = round(y)

		if current then indY.t = current.y end
		if snapHighlight then
			indY:snap(indY.t)
			snapHighlight = false
		end
		local indent = current and current.indent or 0
		highlight.Position = UDim2.fromOffset(8 + indent, round(indY.x))
		highlight.Size = UDim2.new(1, -16 - indent, 0, TAB_H)
		highlight.BackgroundTransparency = 1 - 0.07 * (current and current.fade or 1)

		for _, tab in ipairs(tabs) do
			local a, hv = tab.active.x, tab.st.hover.x
			tab.label.TextColor3 = C.tabIdle:Lerp(C.hi, math.max(hv * 0.85, a))
			tab.label.TextTransparency = 1 - tab.fade
			tab.icon.ImageColor3 = C.tabIdle:Lerp(C.hi, hv * 0.85):Lerp(accent, a)
			tab.icon.ImageTransparency = 1 - tab.fade
			tab.btn.BackgroundTransparency = 1 - 0.03 * hv * (1 - a)
		end
		if current then current.page.Position = UDim2.fromOffset(0, round(pageY.x)) end
		local pf = C.pageFade.x
		pageHost.GroupTransparency = pf < 0.004 and 0 or pf * pf * (3 - 2 * pf)
	end)
end

