local function fieldButton(props)
	props.BackgroundColor3 = C.field
	local b = button(props, { corner(6) })
	local s = stroke(C.fieldStroke, b)
	local sc = new("UIScale", { Parent = b })
	return b, s, sc
end
local function iconButton(img, size, props)
	props.Size = props.Size or UDim2.fromOffset(26, 26)
	local b = button(props, { corner(6) })
	local ic = icon(img, size, { Position = UDim2.fromScale(0.5, 0.5), ImageColor3 = C.dim, Parent = b })
	local st = hoverable(b)
	return b, ic, st
end

do -- scoped: Luau caps a function at 200 locals
	local bar = new("Frame", {
