	local dropSt = hoverable(dropBtn)

	local function flashSaved()
		savedA.t = 1
		savedToken += 1
		local my = savedToken
		task.delay(1.1, function()
			if savedToken == my then savedA.t = 0 end
		end)
	end

	on(saveBtn.Activated, function()
		if not selected then selected = uniqueName(DIR_CFG, "default") end
		if not pcall(Configs.save, selected) then return end
		saveState()
		refreshConfigs()
		flashSaved()
	end)

	---------------------------------------------------- presets popup

	local POP_W = 300
	local LIST_Y = 86
	local CROW_H, CROW_GAP = 36, 6
	local pop = Popup.new(POP_W, 200, 0.03)
	C.presetsInner = pop.inner
	pop.dir = -1
	local view = "configs"
	local sortDesc = false
	local adding = false
	local rows = {}

	local pill = new("Frame", { BorderSizePixel = 0, Position = UDim2.fromOffset(8, 8), Size = UDim2.fromOffset(100, 30), Parent = pop.inner }, { corner(6) })
	bindAccent(pill, function(c) pill.BackgroundColor3 = c end)
	pill.BackgroundTransparency = 0.86
	local pillIcon = icon(ICON.cloud, 15, { Position = UDim2.fromOffset(19, 15), Parent = pill })
	local pillLbl = label({ Text = "Presets", Font = Enum.Font.BuilderSansMedium, TextSize = 13, Position = UDim2.fromOffset(34, 0), Size = UDim2.new(1, -34, 1, 0), Parent = pill })
	bindAccent(pillIcon, function(c) pillIcon.ImageColor3 = c end)
	bindAccent(pillLbl, function(c) pillLbl.TextColor3 = c:Lerp(Color3.new(1, 1, 1), 0.3) end)

	local plusBtn, plusIcon, plusSt = iconButton(ICON.plus, 15, { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -8, 0, 10), Parent = pop.inner })
	local binBtn, binIcon, binSt = iconButton(ICON.trash, 15, { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -38, 0, 10), Parent = pop.inner })

	local search = new("Frame", { BackgroundColor3 = C.field, BorderSizePixel = 0, Position = UDim2.fromOffset(8, 46), Size = UDim2.new(1, -50, 0, 30), Parent = pop.inner }, { corner(6) })
	local searchStroke = stroke(C.fieldStroke, search)
	icon(ICON.search, 14, { Position = UDim2.fromOffset(16, 15), ImageColor3 = C.faint, Parent = search })
	local searchBox = new("TextBox", {
		Text = "", PlaceholderText = "Search", PlaceholderColor3 = C.faint, ClearTextOnFocus = false,
		Font = Enum.Font.BuilderSans, TextSize = 13, TextColor3 = C.hi, TextXAlignment = Enum.TextXAlignment.Left,
		BackgroundTransparency = 1, Position = UDim2.fromOffset(31, 0), Size = UDim2.new(1, -38, 1, 0), Parent = search,
	})
	local searchSt = hoverable(searchBox)
	local sortBtn, sortIcon, sortSt = iconButton(ICON.sort, 15, { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -8, 0, 46), Size = UDim2.fromOffset(32, 30), Parent = pop.inner })
	local sortRot = spring(0, 22, 0.05)

	local list = new("ScrollingFrame", {
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Position = UDim2.fromOffset(0, LIST_Y),
		Size = UDim2.new(1, 0, 0, 40),
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 3,
		ScrollBarImageColor3 = C.faint,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		Parent = pop.inner,
	}, {
		new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, CROW_GAP) }),
		new("UIPadding", { PaddingTop = UDim.new(0, 2), PaddingBottom = UDim.new(0, 8), PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 10) }),
	})
	local emptyLbl = label({
		Text = "", TextColor3 = C.faint, TextXAlignment = Enum.TextXAlignment.Center,
		Position = UDim2.fromOffset(0, LIST_Y), Size = UDim2.new(1, 0, 0, 40), Visible = false, Parent = pop.inner,
	})

	local function rowMenu(name, trash, anchor, atMouse)
		local items
		if trash then
			items = {
				{ icon = ICON.restore, text = "Restore", fn = function() Configs.restore(name) end },
				{ icon = ICON.trash, text = "Delete forever", danger = true, fn = function() Configs.purge(name) end },
			}
		else
			items = {
				{ icon = ICON.copy, text = "Duplicate", fn = function() Configs.duplicate(name) end },
				{ icon = ICON.share, text = "Share", fn = function() Configs.share(name) end },
				{ icon = ICON.users, text = "Send to player", fn = function() if Configs.sendTo then Configs.sendTo(name, anchor) end end },
				{ icon = ICON.trash, text = "Delete", danger = true, fn = function() Configs.delete(name) end },
			}
		end
		if atMouse then
			contextAtMouse(items, anchor)
		else
			local r = relPos(anchor)
			openContext(items, Vector2.new(r.X + anchor.AbsoluteSize.X / C.S() + 6, r.Y - 4), anchor)
		end
	end

	local function buildRow(name, i, trash, animate)
		local isSel = not trash and name == selected
		local r = button({ BackgroundColor3 = C.card, Size = UDim2.new(1, 0, 0, CROW_H), LayoutOrder = i, Parent = list }, { corner(6) })
		local rs = stroke(C.cardStroke, r)
		-- The name itself is a text box: click it to rename in place. The rest of the row loads.
		local t = new(trash and "TextLabel" or "TextBox", {
			Text = name, Font = Enum.Font.BuilderSans, TextSize = 13, TextColor3 = trash and C.dim or C.text,
			TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
			BackgroundTransparency = 1, AutomaticSize = Enum.AutomaticSize.X,
			Position = UDim2.fromOffset(12, 0), Size = UDim2.new(0, 0, 1, 0), Parent = r,
		}, { new("UISizeConstraint", { MinSize = Vector2.new(24, 0), MaxSize = Vector2.new(POP_W - 112, 1e4) }) })
		local editing = false
		if not trash then
			t.ClearTextOnFocus = false
			on(t.Focused, function() editing = true end)
			on(t.FocusLost, function()
				editing = false
				local newName = t.Text
				if sanitize(newName) ~= "" and newName ~= name then
					Configs.rename(name, newName)
				else
					t.Text = name
				end
			end)
		end
		local act, actIcon, actSt = iconButton(trash and ICON.restore or (isSel and ICON.save or ICON.load), 15, {
			AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -6, 0.5, 0), Parent = r,
		})
		local actCheck = icon(ICON.check, 15, { Position = UDim2.fromScale(0.5, 0.5), ImageTransparency = 1, Parent = act })
		bindAccent(actCheck, function(c) actCheck.ImageColor3 = c end)
		local dots, dotsIcon, dotsSt = iconButton(ICON.dots, 14, {
			AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -34, 0.5, 0), Parent = r,
		})
		local st, tSt = hoverable(r), hoverable(t)
		local sel = spring(isSel and 1 or 0, 26)
		local edit = spring(0, 26)
		local appear = spring(animate and 0 or 1, 26, 1e-3)
		local flash = spring(0, 22, 1e-3)
		if animate then task.delay(0.025 * (i - 1), function() appear.t = 1 end) end
		onFrame(function()
			if not r.Parent then
				springs[sel], springs[edit], springs[appear], springs[flash] = nil, nil, nil, nil
				return true
			end
			local a, hv = appear.x, math.max(st.hover.x, actSt.hover.x, dotsSt.hover.x, tSt.hover.x)
			sel.t = (not trash and name == selected) and 1 or 0
			edit.t = editing and 1 or 0
			r.BackgroundColor3 = C.card:Lerp(C.fieldHover, hv * 0.6 + sel.x * 0.25)
			rs.Color = C.cardStroke:Lerp(C.fieldStroke, hv):Lerp(accent:Lerp(C.cardStroke, 0.45), sel.x):Lerp(accent, edit.x)
			t.TextTransparency = 1 - a
			t.TextColor3 = (trash and C.dim or C.text):Lerp(C.hi, math.max(hv * 0.7, sel.x, edit.x))
			t.Position = UDim2.fromOffset(round(12 + (1 - a) * 6), 0)
			act.BackgroundTransparency = 1 - 0.06 * actSt.hover.x
			actIcon.ImageColor3 = C.dim:Lerp(C.hi, actSt.hover.x)
			actIcon.ImageTransparency = math.max(1 - a, flash.x)
			actCheck.ImageTransparency = 1 - flash.x
			dots.BackgroundTransparency = 1 - 0.06 * dotsSt.hover.x
			dotsIcon.ImageColor3 = C.faint:Lerp(C.dim, hv):Lerp(C.hi, dotsSt.hover.x)
			dotsIcon.ImageTransparency = 1 - a
		end)
		on(r.Activated, function()
			if trash or editing or hovered[dots] or hovered[act] or hovered[t] then return end
			Configs.load(name)
		end)
		on(act.Activated, function()
			if trash then
				Configs.restore(name)
			elseif name == selected then
				if pcall(Configs.save, name) then
					flash.t = 1
					task.delay(0.9, function() flash.t = 0 end)
					flashSaved()
				end
			else
				Configs.load(name)
			end
		end)
		on(dots.Activated, function() rowMenu(name, trash, dots) end)
		-- right click anywhere on the row opens the same menu at the cursor
		local lastMenu = 0
		local function rightClick()
			if os.clock() - lastMenu < 0.15 then return end
			lastMenu = os.clock()
			rowMenu(name, trash, r, true)
		end
		on(r.MouseButton2Click, rightClick)
		on(t.InputEnded, function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton2 then rightClick() end
		end)
		return r
	end

	local nameRow, nameBox
	local function buildNameRow()
		nameRow = new("Frame", { BackgroundColor3 = C.card, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, CROW_H), LayoutOrder = 0, Parent = list }, { corner(6) })
		local s = stroke(accent, nameRow)
		bindAccent(s, function(c) s.Color = c end)
		nameBox = new("TextBox", {
			Text = "", PlaceholderText = "Config name", PlaceholderColor3 = C.faint, ClearTextOnFocus = false,
			Font = Enum.Font.BuilderSans, TextSize = 13, TextColor3 = C.hi, TextXAlignment = Enum.TextXAlignment.Left,
			BackgroundTransparency = 1, Position = UDim2.fromOffset(12, 0), Size = UDim2.new(1, -24, 1, 0), Parent = nameRow,
		})
		on(nameBox.FocusLost, function(enter)
			local text = nameBox.Text
			adding = false
			if enter then Configs.create(text) else refreshConfigs() end
		end)
		task.defer(function() if nameBox and nameBox.Parent then nameBox:CaptureFocus() end end)
	end

	local function render(animate)
		for _, r in ipairs(rows) do r:Destroy() end
		table.clear(rows)
		if nameRow then nameRow:Destroy(); nameRow, nameBox = nil, nil end

		local trash = view == "trash"
		local all = listNames(trash and DIR_TRASH or DIR_CFG)
		local q = searchBox.Text:lower()
		local shown = {}
		for _, n in ipairs(all) do
			if q == "" or n:lower():find(q, 1, true) then shown[#shown + 1] = n end
		end
		table.sort(shown, function(a, b)
			if sortDesc then return a:lower() > b:lower() end
			return a:lower() < b:lower()
		end)
		if adding and not trash then buildNameRow() end
		for i, n in ipairs(shown) do rows[i] = buildRow(n, i, trash, animate) end
		emptyLbl.Visible = #shown == 0 and not (adding and not trash)
		emptyLbl.Text = (#all == 0) and (trash and "Trash is empty" or "No configs") or "Nothing found"
		pillIcon.Image = trash and ICON.trash or ICON.cloud
		pillLbl.Text = trash and "Trash" or "Presets"
	end

	refreshConfigs = function()
		local names = listNames(DIR_CFG)
		if selected and not table.find(names, selected) then selected = nil end
		dropLabel.Text = selected or "No config"
		dropLabel.TextColor3 = selected and C.text or C.dim
		if pop.open then render(false) end
	end

	local function setView(v)
		if view == v then return end
		view = v
		adding = false
		render(true)
	end

	on(binBtn.Activated, function() setView(view == "trash" and "configs" or "trash") end)
	on(plusBtn.Activated, function()
		view = "configs"
		adding = true
		render(false)
	end)
	on(sortBtn.Activated, function()
		sortDesc = not sortDesc
		render(false)
	end)
	on(searchBox:GetPropertyChangedSignal("Text"), function()
		if pop.open then render(false) end
	end)

	on(dropBtn.Activated, function()
		if pop.open then
			pop:hide()
		else
			pop:show(dropBtn)
			render(true)
		end
	end)
	pop.onHide = function()
		local f = UIS:GetFocusedTextBox()
		if f and f:IsDescendantOf(pop.inner) then f:ReleaseFocus() end
		adding = false
	end

	onFrame(function()
		-- Rise from the bar, never higher than the tab list.
		local ws = winSize()
		local maxH = ws.Y - HEADER_H - 14
		local n = #rows + (nameRow and 1 or 0)
		local listH = n > 0 and (2 + n * (CROW_H + CROW_GAP) - CROW_GAP + 8) or 44
		pop.h.t = math.min(LIST_Y + listH + 4, maxH)
		pop.pos = Vector2.new(SIDE_W + 9, HEADER_H - 4)
		pop.bottom = nil
		list.Size = UDim2.new(1, 0, 0, math.max(0, round(pop.h.x) - LIST_Y - 4))

		local pw = 34 + textWidth(pillLbl.Text, 13, Enum.Font.BuilderSansMedium) + 12
		pill.Size = UDim2.fromOffset(round(pw), 30)

		plusBtn.BackgroundTransparency = 1 - 0.06 * plusSt.hover.x
		plusIcon.ImageColor3 = C.dim:Lerp(C.hi, plusSt.hover.x)
		binBtn.BackgroundTransparency = 1 - 0.06 * binSt.hover.x
		binIcon.ImageColor3 = (view == "trash" and accent or C.dim):Lerp(C.hi, view == "trash" and 0 or binSt.hover.x)
		sortBtn.BackgroundTransparency = 1 - 0.06 * sortSt.hover.x
		sortIcon.ImageColor3 = C.dim:Lerp(C.hi, sortSt.hover.x)
		sortRot.t = sortDesc and 180 or 0
		sortIcon.Rotation = sortRot.x
		local focused = searchBox:IsFocused() and 1 or 0
		search.BackgroundColor3 = C.field:Lerp(C.fieldHover, math.max(searchSt.hover.x * 0.6, focused))
		searchStroke.Color = C.fieldStroke:Lerp(accent, focused)

		-- config bar
		local s = savedA.x
		saveIcon.ImageTransparency = s
		saveIcon.Size = UDim2.fromOffset(16 * (1 - 0.4 * s), 16 * (1 - 0.4 * s))
		saveIcon.ImageColor3 = C.text:Lerp(C.hi, saveSt.hover.x)
		checkIcon.ImageTransparency = 1 - s
		checkIcon.Size = UDim2.fromOffset(16 * (0.6 + 0.4 * s), 16 * (0.6 + 0.4 * s))
		saveBtn.BackgroundTransparency = 1 - 0.04 * saveSt.hover.x - 0.03 * saveSt.press.x
		local openA = 1 - pop.alpha.x
		dropBtn.BackgroundTransparency = 1 - 0.04 * math.max(dropSt.hover.x, openA) - 0.03 * dropSt.press.x
		local edge = C.fieldStroke:Lerp(C.dim, math.max(saveSt.hover.x, dropSt.hover.x, openA) * 0.45):Lerp(accent, s * 0.6)
		barStroke.Color = edge
		barDivider.BackgroundColor3 = edge
		dropChevron.Rotation = 180 * openA
		dropChevron.ImageColor3 = C.dim:Lerp(C.hi, dropSt.hover.x)
	end)
end

inject()

---------------------------------------------------------------- color picker popup

local function checker(parent, props)
	props.Image = ICON.checker
	props.ScaleType = Enum.ScaleType.Tile
	props.TileSize = UDim2.fromOffset(8, 8)
	props.ResampleMode = Enum.ResamplerMode.Pixelated
	props.BackgroundTransparency = 1
	props.Parent = parent
	return new("ImageLabel", props)
end

local picker, pickValue, pickTarget, pickDrag, openPicker, colorMenu
