	checker(alphaBar, { Size = UDim2.fromScale(1, 1) })
	local alphaFill = new("Frame", { BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), Parent = alphaBar },
		{ new("UIGradient", { Transparency = NumberSequence.new(1, 0) }) })
	local alphaThumb, alphaThumbFill, alphaScale = ringThumb(10, 18, 5)

	local function smallField(x, w)
