	end

	local fmtBtn, _, fmtScale = fieldButton({ Position = UDim2.fromOffset(10, Y_ROW), Size = UDim2.fromOffset(48, 22), Parent = body })
	fmtBtn:FindFirstChildOfClass("UICorner").CornerRadius = UDim.new(0, 4)
	local fmtLbl = label({ Text = "HEX", Font = Enum.Font.BuilderSansMedium, TextSize = 11, Position = UDim2.fromOffset(8, 0), Size = UDim2.new(1, -8, 1, 0), Parent = fmtBtn })
	local fmtChevron = icon(ICON.chevron, 10, { Position = UDim2.new(1, -10, 0.5, 0), ImageColor3 = C.dim, Parent = fmtBtn })
	local fmtSt = hoverable(fmtBtn)

	local preview = button({ Position = UDim2.fromOffset(63, Y_ROW + 3), Size = UDim2.fromOffset(16, 16), Parent = body })
	corner(4).Parent = checker(preview, { Size = UDim2.fromScale(1, 1) })
	local previewFill = new("Frame", { BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), Parent = preview }, { corner(4) })
	new("UIStroke", { Color = C.fieldStroke, Thickness = 1, Parent = preview })
	hoverable(preview)

	local hexField = smallField(84, 86)
	local f1, f2, f3 = smallField(84, 26), smallField(114, 26), smallField(144, 26)
	local alphaField = smallField(175, 38)

	local gridBtn, gridStroke, gridScale = fieldButton({ Position = UDim2.fromOffset(218, Y_ROW), Size = UDim2.fromOffset(22, 22), Parent = body })
	gridBtn:FindFirstChildOfClass("UICorner").CornerRadius = UDim.new(0, 4)
	local gridIcon = icon(ICON.grid, 12, { Position = UDim2.fromScale(0.5, 0.5), ImageColor3 = C.dim, Parent = gridBtn })
	local gridSt = hoverable(gridBtn)

	-- favorites: the + slot saves the current color; right click a saved one to delete it
	local FAV_FILE = ROOT .. "/favorites.json"
	local MAX_FAV = 9
	local favs = {}
	do
		local ok, t = pcall(function() return HttpService:JSONDecode(readfile(FAV_FILE)) end)
		if ok and type(t) == "table" then
			for _, h in ipairs(t) do
				if type(h) == "string" and parseHex(h) then favs[#favs + 1] = h end
			end
		end
	end
	local function saveFavs() pcall(writefile, FAV_FILE, HttpService:JSONEncode(favs)) end
	local function slotX(i) return 10 + round((i - 1) * (PICK_W - 18) / MAX_FAV) end

	local addSc = new("UIScale", {})
	local addBtn = button({
		BackgroundColor3 = C.field, AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromOffset(slotX(1) + 9, Y_PRESETS + 9), Size = UDim2.fromOffset(18, 18), Parent = body,
	}, { corner(4), addSc })
	local addStroke = stroke(C.fieldStroke, addBtn)
	local addIcon = icon(ICON.plus, 11, { Position = UDim2.fromScale(0.5, 0.5), ImageColor3 = C.dim, Parent = addBtn })
	local addSt = hoverable(addBtn)

	local favBtns = {}
	local renderFavs
	renderFavs = function()
		for _, f in ipairs(favBtns) do f.btn:Destroy() end
		table.clear(favBtns)
		for i, hex in ipairs(favs) do
			local col, a = parseHex(hex)
			local sc = new("UIScale", {})
			local b = button({
				AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(slotX(i + 1) + 9, Y_PRESETS + 9),
				Size = UDim2.fromOffset(18, 18), Parent = body,
			}, { corner(4), sc })
			corner(4).Parent = checker(b, { Size = UDim2.fromScale(1, 1) })
			new("Frame", { BackgroundColor3 = col, BackgroundTransparency = 1 - (a or 1), BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), Parent = b }, { corner(4) })
			on(b.Activated, function()
				if pickValue then pickValue:setRGB(col, a or 1) end
			end)
			on(b.MouseButton2Click, function()
				contextAtMouse({
					{ icon = ICON.trash, text = "Delete", danger = true, fn = function()
						local j = table.find(favs, hex)
						if j then table.remove(favs, j) end
						saveFavs()
						renderFavs()
					end },
				}, b)
			end)
			favBtns[i] = { btn = b, st = hoverable(b), sc = sc }
		end
	end
	renderFavs()
	on(addBtn.Activated, function()
		if not pickValue then return end
		local hex = hex8(pickValue)
		if table.find(favs, hex) then return end
		if #favs >= MAX_FAV then table.remove(favs, 1) end
		favs[#favs + 1] = hex
		saveFavs()
		renderFavs()
	end)

	-- color chips on top when one setting has several colors (e.g. health max/min)
	local chips = new("Frame", {
		BackgroundTransparency = 1, Position = UDim2.fromOffset(10, 8), Size = UDim2.new(1, -20, 0, 24), Parent = picker.inner,
	}, {
		new("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal, HorizontalAlignment = Enum.HorizontalAlignment.Center,
			VerticalAlignment = Enum.VerticalAlignment.Center, Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder,
		}),
	})
	local chipObjs = {}
	local function buildChips()
		for _, c in ipairs(chipObjs) do c:Destroy() end
		table.clear(chipObjs)
		chips.Visible = #pickList > 1
		if #pickList < 2 then return end
		for i, e in ipairs(pickList) do
			local name = e.name or ("Color " .. i)
			local tw = textWidth(name, 12, Enum.Font.BuilderSansMedium)
			local chip = button({ BackgroundColor3 = C.field, BackgroundTransparency = 1, ClipsDescendants = true, Size = UDim2.fromOffset(24, 24), LayoutOrder = i, Parent = chips }, { corner(6) })
			local cs = stroke(C.fieldStroke, chip)
			local sq = new("Frame", { BorderSizePixel = 0, AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 6, 0.5, 0), Size = UDim2.fromOffset(12, 12), Parent = chip }, { corner(3) })
			local lbl = label({ Text = name, Font = Enum.Font.BuilderSansMedium, TextColor3 = C.hi, Position = UDim2.fromOffset(24, 0), Size = UDim2.new(0, tw + 4, 1, 0), Parent = chip })
			local st = hoverable(chip)
			local sel = spring(i == pickIndex and 1 or 0, 26)
			on(chip.Activated, function()
				pickIndex = i
				pickValue = e.cv
			end)
			onFrame(function()
				if not chip.Parent then
					springs[sel] = nil
					return true
				end
				sel.t = i == pickIndex and 1 or 0
				chip.Size = UDim2.fromOffset(round(24 + sel.x * (tw + 8)), 24)
				chip.BackgroundTransparency = 1 - sel.x - 0.04 * st.hover.x * (1 - sel.x)
				cs.Transparency = 1 - sel.x
				lbl.TextTransparency = 1 - sel.x
				sq.BackgroundColor3 = e.cv:display()
				sq.BackgroundTransparency = 1 - e.cv.da.x
			end)
			chipObjs[i] = chip
		end
	end

	local function setFieldsVisible()
		hexField.Visible = pickMode == "HEX"
		f1.Visible, f2.Visible, f3.Visible = pickMode ~= "HEX", pickMode ~= "HEX", pickMode ~= "HEX"
		fmtLbl.Text = pickMode
	end
	setFieldsVisible()

	local function fieldValues()
		local cv = pickValue
		if pickMode == "RGB" then
			local r, g, b = to255(cv:rgb())
			return r, g, b
		end
		return round(cv.h * 360) % 361, round(cv.s * 100), round(cv.v * 100)
	end

	local function applyTriple(i, n)
		local cv = pickValue
		if pickMode == "RGB" then
			local c = { to255(cv:rgb()) }
			c[i] = math.clamp(round(n), 0, 255)
			cv:setRGB(Color3.fromRGB(c[1], c[2], c[3]))
		else
			local hsv = { cv.h * 360, cv.s * 100, cv.v * 100 }
			hsv[i] = math.clamp(n, 0, i == 1 and 360 or 100)
			cv:set(hsv[1] / 360, hsv[2] / 100, hsv[3] / 100, cv.a)
		end
	end

	for i, f in ipairs({ f1, f2, f3 }) do
		on(f.FocusLost, function()
			local n = tonumber((f.Text:gsub("[^%d%.%-]", "")))
			if n and pickValue then applyTriple(i, n) end
		end)
		onWheel(f, function(d)
			if not pickValue then return end
			local vals = { fieldValues() }
			applyTriple(i, vals[i] + d)
		end)
	end
	on(hexField.FocusLost, function()
		local c, a = parseHex(hexField.Text)
		if c and pickValue then pickValue:setRGB(c, a or pickValue.a) end
	end)
	onWheel(hexField, function(d)
		local cv = pickValue
		if cv then cv:set(cv.h, cv.s, (round(cv.v * 100) + d) / 100, cv.a) end
	end)
	on(alphaField.FocusLost, function()
		local n = tonumber((alphaField.Text:gsub("[^%d%.]", "")))
		if n and pickValue then pickValue:set(pickValue.h, pickValue.s, pickValue.v, n / 100) end
	end)
	local function alphaWheel(d)
		local cv = pickValue
		if cv then cv:set(cv.h, cv.s, cv.v, (round(cv.a * 100) + d) / 100) end
	end
	onWheel(alphaField, alphaWheel)
	onWheel(alphaBar, alphaWheel)
	onWheel(hueBar, function(d)
		local cv = pickValue
		if cv then cv:set((round(cv.h * 360) + d) / 360, cv.s, cv.v, cv.a) end
	end)
	onWheel(svBox, function(d, shift)
		local cv = pickValue
		if not cv then return end
		if shift then
			cv:set(cv.h, (round(cv.s * 100) + d / 10) / 100, cv.v, cv.a) -- shift: saturation, one step per notch
		else
			cv:set(cv.h, cv.s, (round(cv.v * 100) + d) / 100, cv.a)
		end
	end)

	on(fmtBtn.Activated, function()
		pickMode = pickMode == "HEX" and "RGB" or pickMode == "RGB" and "HSV" or "HEX"
		setFieldsVisible()
	end)
	on(gridBtn.Activated, function() presetsOpen = not presetsOpen end)

	local function beginPick(kind)
		return function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				pickDrag = kind
			end
		end
	end
	on(svBox.InputBegan, beginPick("sv"))
	on(hueBar.InputBegan, beginPick("hue"))
	on(alphaBar.InputBegan, beginPick("alpha"))

	local svPress, huePress, alphaPress = spring(0, 30), spring(0, 30), spring(0, 30)

	local function contentH() return presetsOpen and (Y_PRESETS + 28) or (Y_ROW + 32) end

	-- target: a ColorValue, or a list of { name, cv } for settings with several colors
	openPicker = function(target, anchor)
		if picker.open and pickTarget == target then
			picker:hide()
			return
		end
		pickTarget = target
		pickList = target.dh and { { cv = target } } or target
		pickIndex = 1
		pickValue = pickList[1].cv
		buildChips()
		local top = #pickList > 1 and (10 + CHIPS_H) or 10
		bodyTop:snap(top)
		local h = top + contentH()
		picker.h:snap(h)
		picker:placeAt(anchor, h, true)
		picker:show(anchor)
	end

	colorMenu = function(target, anchor)
		local list = target.dh and { { cv = target } } or target
		local clip = colorClip and Color3.fromHSV(colorClip[1], colorClip[2], colorClip[3])
		local items = {}
		for _, e in ipairs(list) do
			local cv = e.cv
			local suffix = e.name and (" " .. e.name) or ""
			items[#items + 1] = {
				icon = ICON.copy, text = "Copy" .. suffix,
				fn = function()
					colorClip = { cv.h, cv.s, cv.v, cv.a }
					if setclipboard then pcall(setclipboard, "#" .. hex8(cv)) end
					toast("Copied #" .. hex8(cv))
				end,
			}
			items[#items + 1] = {
				swatch = clip or C.faint, text = "Paste" .. suffix, disabled = clip == nil,
				fn = function() cv:set(colorClip[1], colorClip[2], colorClip[3], colorClip[4]) end,
			}
			items[#items + 1] = {
				icon = ICON.restore, text = "Reset" .. suffix,
				fn = function() if cv.def then cv:setRGB(cv.def[1], cv.def[2]) end end,
			}
		end
		contextAtMouse(items, anchor)
	end
	on(preview.MouseButton2Click, function() if pickValue then colorMenu(pickValue, preview) end end)

	onFrame(function()
		local cv = pickValue
		if not cv then return end
		if pickDrag and picker.open then
			local m = mouseAbs()
			if pickDrag == "sv" then
				local a, s = svBox.AbsolutePosition, svBox.AbsoluteSize
				cv:set(cv.h, clamp01((m.X - a.X) / s.X), 1 - clamp01((m.Y - a.Y) / s.Y), cv.a)
			elseif pickDrag == "hue" then
				local a, s = hueBar.AbsolutePosition, hueBar.AbsoluteSize
				cv:set(clamp01((m.X - a.X) / s.X), cv.s, cv.v, cv.a)
			else
				local a, s = alphaBar.AbsolutePosition, alphaBar.AbsoluteSize
				cv:set(cv.h, cv.s, cv.v, clamp01((m.X - a.X) / s.X))
			end
		end

		picker.h.t = bodyTop.t + contentH()
		body.Position = UDim2.fromOffset(0, round(bodyTop.x))

		local col = cv:display()
		local hueCol = Color3.fromHSV(cv.dh.x, 1, 1)
		svBox.BackgroundColor3 = hueCol
		svThumb.Position = UDim2.fromOffset(10 + cv.ds.x * PICK_W, (1 - cv.dv.x) * SV_H)
		svFill.BackgroundColor3 = col
		hueThumb.Position = UDim2.fromOffset(10 + cv.dh.x * PICK_W, Y_HUE + 4)
		hueFill.BackgroundColor3 = hueCol
		alphaThumb.Position = UDim2.fromOffset(10 + cv.da.x * PICK_W, Y_ALPHA + 4)
		alphaThumbFill.BackgroundColor3 = col
		alphaFill.BackgroundColor3 = col
		previewFill.BackgroundColor3 = col
		previewFill.BackgroundTransparency = 1 - cv.da.x

		svPress.t = pickDrag == "sv" and 1 or 0
		huePress.t = pickDrag == "hue" and 1 or 0
		alphaPress.t = pickDrag == "alpha" and 1 or 0
		svScale.Scale = 1 + svPress.x * 0.18
		hueScale.Scale = 1 + huePress.x * 0.12
		alphaScale.Scale = 1 + alphaPress.x * 0.12

		if not hexField:IsFocused() then
			local s = "#" .. hex6(cv:rgb())
			C.setText(hexField, s)
		end
		if pickMode ~= "HEX" then
			local vals = { fieldValues() }
			for i, f in ipairs({ f1, f2, f3 }) do
				local s = tostring(vals[i])
				if not f:IsFocused() and f.Text ~= s then f.Text = s end
			end
		end
		if not alphaField:IsFocused() then
			local s = round(cv.a * 100) .. "%"
			C.setText(alphaField, s)
		end

		fmtBtn.BackgroundColor3 = C.field:Lerp(C.fieldHover, fmtSt.hover.x)
		fmtScale.Scale = 1 - fmtSt.press.x * 0.06
		fmtChevron.ImageColor3 = C.dim:Lerp(C.hi, fmtSt.hover.x)
		gridBtn.BackgroundColor3 = C.field:Lerp(C.fieldHover, gridSt.hover.x)
		gridScale.Scale = 1 - gridSt.press.x * 0.08
		gridIcon.ImageColor3 = presetsOpen and accent or C.dim:Lerp(C.hi, gridSt.hover.x)
		gridStroke.Color = presetsOpen and accent or C.fieldStroke
		addBtn.BackgroundColor3 = C.field:Lerp(C.fieldHover, addSt.hover.x)
		addStroke.Color = C.fieldStroke:Lerp(C.dim, addSt.hover.x * 0.6)
		addIcon.ImageColor3 = C.dim:Lerp(C.hi, addSt.hover.x)
		addSc.Scale = 1 - addSt.press.x * 0.1
		for _, f in ipairs(favBtns) do
			if f.btn.Parent then f.sc.Scale = 1 + f.st.hover.x * 0.12 - f.st.press.x * 0.1 end
		end
	end)
end)()

inject()

---------------------------------------------------------------- group boxes & controls

local listeningBind -- keybind control waiting for input

local function columns(page)
	local cols = {}
	for i = 0, 1 do
		cols[i] = new("Frame", {
			BackgroundTransparency = 1,
			Position = UDim2.new(i * 0.5, i == 0 and 14 or 7, 0, 0),
			Size = UDim2.new(0.5, -21, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Parent = page,
		}, { new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 16) }) })
	end
	return cols[0], cols[1]
end

local function group(col, title)
	local wrap = new("Frame", {
		BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = #col:GetChildren(), Parent = col,
	}, { new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 7) }) })
	label({ Text = title:upper(), Font = Enum.Font.BuilderSansBold, TextSize = 10, TextColor3 = C.section, Position = UDim2.fromOffset(2, 0), Size = UDim2.new(1, 0, 0, 12), LayoutOrder = 0, Parent = wrap })
	local box = new("Frame", {
		BackgroundColor3 = C.box, BackgroundTransparency = 0.06, BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1, Parent = wrap,
	}, { corner(10), new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }) })
	stroke(C.boxStroke, box)
	return box
end

-- A row in a group box: label on the left (truncated with "...", scrolls on hover when it doesn't
-- fit), controls on the right. Returns the row, a setter for the controls' width, and hover state.
local boxRows = setmetatable({}, { __mode = "k" })
local function itemRow(box, text)
	local n = boxRows[box] or 0
	boxRows[box] = n + 1
	local r = button({ Size = UDim2.new(1, 0, 0, ROW_H), LayoutOrder = (n + 1) * 100, Parent = box }, { corner(10) })
	C.rows[r] = text
	if n > 0 then
		new("Frame", { BackgroundColor3 = C.rowLine, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 1), Parent = r })
	end
	local clip = new("Frame", { BackgroundTransparency = 1, ClipsDescendants = true, Position = UDim2.fromOffset(14, 0), Size = UDim2.new(1, -28, 1, 0), Parent = r })
	local lbl = label({ Text = text, TextSize = 13, TextColor3 = C.text, TextTruncate = Enum.TextTruncate.AtEnd, Size = UDim2.fromScale(1, 1), Parent = clip })
	local st = hoverable(r)
	local full = textWidth(text, 13, Enum.Font.BuilderSans)
	local rightW = 0
	local off = spring(0, 16, 0.05)
	local t = 0
	local PAUSE, SPEED = 0.8, 32
	onFrame(function(dt)
		if not r.Parent then return true end
		r.BackgroundTransparency = 1 - 0.018 * st.hover.x
		lbl.TextColor3 = C.text:Lerp(C.hi, st.hover.x * 0.5)
		clip.Size = UDim2.new(1, -28 - rightW, 1, 0)
		local over = full - clip.AbsoluteSize.X / C.S()
		local scrolling = over > 1 and st.hover.t == 1
		if scrolling then
			-- ping-pong with pauses at both ends
			t += dt
			local travel = over / SPEED
			local p = t % (2 * (PAUSE + travel))
			local x
			if p < PAUSE then x = 0
			elseif p < PAUSE + travel then x = smooth((p - PAUSE) / travel) * over
			elseif p < 2 * PAUSE + travel then x = over
			else x = (1 - smooth((p - 2 * PAUSE - travel) / travel)) * over end
			off:snap(x)
		else
			t = 0
			off.t = 0 -- glide back, then truncate again
		end
		if scrolling or off.x > 0.5 then
			lbl.TextTruncate = Enum.TextTruncate.None
			lbl.Size = UDim2.new(0, full + 4, 1, 0)
			lbl.Position = UDim2.fromOffset(-round(off.x), 0)
		else
			lbl.TextTruncate = Enum.TextTruncate.AtEnd
			lbl.Size = UDim2.fromScale(1, 1)
			lbl.Position = UDim2.new()
		end
	end)
	return r, function(w) rightW = w end, st
end

---------------------------------------------------------------- hotkeys

local functions = {} -- toggle id -> record, see toggleControl
local hotkeys = {} -- every bind, in creation order
local attachHotkeys, hotkeyInput
do
	local HK_ROW = 28
	local BP_H = 149
	local hkPop = Popup.new(160, 100, 0.12) -- right click menu of one function, binds listed inside
	local bindPop = Popup.new(210, BP_H, 0.12) -- settings of the hovered bind
	local allPop = Popup.new(270, 100, 0.12)
	local hkRec, hkAt = nil, Vector2.zero
	local hkRows = {}
	local popBind, popRow
	local lastInside = 0
	local removeBind, openBindPop, openAll

	---------------- bind settings, opens while hovering a bind
	for _, rowDef in ipairs({ { 6, "Key" }, { 40, "Mode" }, { 74, "Value" } }) do
		label({ Text = rowDef[2], TextSize = 12, TextColor3 = C.dim, Position = UDim2.fromOffset(12, rowDef[1]), Size = UDim2.fromOffset(80, 30), Parent = bindPop.inner })
	end

	local keyBtn, keyStroke = fieldButton({ AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -10, 0, 9), Size = UDim2.fromOffset(84, 24), Parent = bindPop.inner })
	keyBtn:FindFirstChildOfClass("UICorner").CornerRadius = UDim.new(0, 5)
	local keyLbl = label({ Text = "", Font = Enum.Font.BuilderSansMedium, TextXAlignment = Enum.TextXAlignment.Center, TextTruncate = Enum.TextTruncate.AtEnd, Size = UDim2.fromScale(1, 1), Parent = keyBtn })
	local keySt = hoverable(keyBtn)
	on(keyBtn.Activated, function()
		if popBind and os.clock() - popBind.listener.capturedAt > 0.4 then listeningBind = popBind.listener end
	end)

	local seg = new("Frame", {
		BackgroundColor3 = C.field, BorderSizePixel = 0, AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -10, 0, 43), Size = UDim2.fromOffset(116, 24), Parent = bindPop.inner,
	}, { corner(5) })
	stroke(C.fieldStroke, seg)
	local segHi = new("Frame", { BorderSizePixel = 0, BackgroundTransparency = 0.8, Size = UDim2.new(0.5, -4, 1, -4), Parent = seg }, { corner(4) })
	bindAccent(segHi, function(c) segHi.BackgroundColor3 = c end)
	local segX = spring(0, 28, 1e-3)
	local segLbls = {}
	for i, mode in ipairs({ "Hold", "Toggle" }) do
		local b = button({ Position = UDim2.fromScale((i - 1) * 0.5, 0), Size = UDim2.fromScale(0.5, 1), Parent = seg })
		segLbls[mode] = label({ Text = mode, Font = Enum.Font.BuilderSansMedium, TextXAlignment = Enum.TextXAlignment.Center, Size = UDim2.fromScale(1, 1), Parent = b })
		hoverable(b)
		on(b.Activated, function()
			if popBind then
				popBind.mode = mode
				popBind.active = false
			end
		end)
	end

	local vBtn = button({ AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -6, 0, 76), Size = UDim2.fromOffset(42, 26), Parent = bindPop.inner })
	local vTrack = new("Frame", {
		BorderSizePixel = 0, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -4, 0.5, 0), Size = UDim2.fromOffset(30, 18), Parent = vBtn,
	}, { new("UICorner", { CornerRadius = UDim.new(1, 0) }) })
	local vKnob = new("Frame", {
		BorderSizePixel = 0, AnchorPoint = Vector2.new(0, 0.5), Size = UDim2.fromOffset(12, 12), Parent = vTrack,
	}, { new("UICorner", { CornerRadius = UDim.new(1, 0) }) })
	local vSt = hoverable(vBtn)
	local vS = spring(0, 26)
	on(vBtn.Activated, function()
		if popBind then
			popBind.value = not popBind.value
			popBind.active = false
		end
	end)

	new("Frame", { BackgroundColor3 = C.divider, BorderSizePixel = 0, Position = UDim2.fromOffset(0, 110), Size = UDim2.new(1, 0, 0, 1), Parent = bindPop.inner })
	local delBtn = button({ Position = UDim2.fromOffset(5, 114), Size = UDim2.new(1, -10, 0, 30), Parent = bindPop.inner }, { corner(5) })
	local delIcon = icon(ICON.trash, 14, { Position = UDim2.fromOffset(16, 15), ImageColor3 = C.danger, Parent = delBtn })
	local delLbl = label({ Text = "Delete", TextColor3 = C.danger, Position = UDim2.fromOffset(31, 0), Size = UDim2.new(1, -36, 1, 0), Parent = delBtn })
	local delSt = hoverable(delBtn)
	on(delBtn.Activated, function() if popBind then removeBind(popBind) end end)

	openBindPop = function(b, row)
		lastInside = os.clock()
		if popBind == b and bindPop.open then return end
		popBind, popRow = b, row
		local x = hkPop.pos.X + hkPop.w + 6
		if x + bindPop.w > winSize().X - 6 then x = hkPop.pos.X - bindPop.w - 6 end
		bindPop.dir = 1
		bindPop:place(x, relPos(row).Y - 8, BP_H)
		bindPop:show(row)
	end

	onFrame(function()
		local b = popBind
		if not b or not bindPop.open then return end
		local m = mouseAbs()
		local listening = listeningBind == b.listener
		if listening or inside(bindPop.inner, m) or (popRow and popRow.Parent and inside(popRow, m)) then
			lastInside = os.clock()
		elseif os.clock() - lastInside > 0.25 then
			bindPop:hide()
			return
		end
		local t = listening and "..." or (b.key and keyName(b.key) or "None")
		C.setText(keyLbl, t)
		local l = listening and 1 or 0
		local pulse = 0.6 + 0.4 * math.sin(os.clock() * 6)
		keyStroke.Color = C.fieldStroke:Lerp(C.dim, keySt.hover.x * 0.4):Lerp(accent, l * pulse)
		keyBtn.BackgroundColor3 = C.field:Lerp(C.fieldHover, math.max(keySt.hover.x, l) * 0.7)
		keyLbl.TextColor3 = (b.key and C.text or C.dim):Lerp(C.hi, keySt.hover.x):Lerp(accent, l)
		segX.t = b.mode == "Toggle" and 1 or 0
		segHi.Position = UDim2.new(segX.x * 0.5, 2, 0, 2)
		segLbls.Hold.TextColor3 = C.dim:Lerp(C.hi, 1 - segX.x)
		segLbls.Toggle.TextColor3 = C.dim:Lerp(C.hi, segX.x)
		vS.t = b.value and 1 or 0
		vTrack.BackgroundColor3 = C.toggleOff:Lerp(C.fieldStroke, vSt.hover.x * (1 - vS.x) * 0.6):Lerp(accent, vS.x)
		vKnob.BackgroundColor3 = C.knobOff:Lerp(Color3.new(1, 1, 1), vS.x)
		vKnob.Position = UDim2.new(0, round(3 + vS.x * 12), 0.5, 0)
		delBtn.BackgroundTransparency = 1 - 0.06 * delSt.hover.x
		local dc = C.danger:Lerp(rgb(255, 130, 130), delSt.hover.x)
		delIcon.ImageColor3, delLbl.TextColor3 = dc, dc
	end)

	---------------- per-function hotkey menu: All Hotkeys, its binds, New Hotkey, Reset
	local hkList = new("Frame", {
		BackgroundTransparency = 1, Position = UDim2.fromOffset(4, 4), Size = UDim2.new(1, -8, 1, -8), Parent = hkPop.inner,
	}, { new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }) })

	local function hkRow(order, img, text, opts)
		opts = opts or {}
		local r = button({ Size = UDim2.new(1, 0, 0, opts.animate and 0 or HK_ROW), ClipsDescendants = true, LayoutOrder = order, Parent = hkList }, { corner(5) })
		local base = opts.danger and C.danger or C.text
		local ic = icon(img, 14, { Position = UDim2.fromOffset(16, HK_ROW / 2), ImageColor3 = base, Parent = r })
		local t = label({ Text = text, Position = UDim2.fromOffset(31, 0), Size = UDim2.new(1, -36, 0, HK_ROW), Parent = r })
		local st = hoverable(r)
		local e = { row = r, label = t, b = opts.bind, h = spring(opts.animate and 0 or HK_ROW, 26, 0.01) }
		e.h.t = HK_ROW
		hkRows[#hkRows + 1] = e
		onFrame(function()
			if not r.Parent then
				springs[e.h] = nil
				return true
			end
			if e.dead then
				e.h.t = 0
				if e.h.x < 0.5 then
					local i = table.find(hkRows, e)
					if i then table.remove(hkRows, i) end
					r:Destroy()
					return
				end
			end
			r.Size = UDim2.new(1, 0, 0, round(e.h.x))
			r.BackgroundTransparency = 1 - 0.05 * st.hover.x
			local col
			if e.b then
				local listening = listeningBind == e.b.listener
				local txt = listening and "..." or (e.b.key and keyName(e.b.key) or "None")
				C.setText(t, txt)
				col = listening and accent or (e.b.key and C.text or C.dim):Lerp(C.hi, st.hover.x)
			else
				col = base:Lerp(opts.danger and rgb(255, 130, 130) or C.hi, st.hover.x)
			end
			t.TextColor3, ic.ImageColor3 = col, col
		end)
		return e
	end

	local function bindRow(b, animate)
		local e = hkRow(10 + b.seq, ICON.keycap, "", { bind = b, animate = animate })
		b.entry = e
		on(e.row.MouseEnter, function() if not e.dead then openBindPop(b, e.row) end end)
		on(e.row.Activated, function()
			if e.dead then return end
			if os.clock() - b.listener.capturedAt > 0.4 then listeningBind = b.listener end
			openBindPop(b, e.row)
		end)
	end

	local function newBind(rec, data)
		data = data or {}
		local b = { fn = rec.id, key = data.key, mode = data.mode or "Toggle", value = data.value or false, active = false }
		rec.bindSeq = math.min((rec.bindSeq or 0) + 1, 900)
		b.seq = rec.bindSeq
		b.listener = { capturedAt = 0 }
		function b.listener.capture(k)
			b.key = k
			b.active = false
			listeningBind = nil
			b.listener.capturedAt = os.clock()
		end
		hotkeys[#hotkeys + 1] = b
		rec.binds[#rec.binds + 1] = b
		if hkPop.open and hkRec == rec then bindRow(b, true) end
		return b
	end

	removeBind = function(b)
		if b.dead then return end
		b.dead, b.active = true, false
		local i = table.find(hotkeys, b)
		if i then table.remove(hotkeys, i) end
		local rec = functions[b.fn]
		local j = rec and table.find(rec.binds, b)
		if j then table.remove(rec.binds, j) end
		if b.entry then b.entry.dead = true end
		if listeningBind == b.listener then listeningBind = nil end
		if popBind == b then
			bindPop:hide()
			popBind = nil
		end
	end

	local function openHotkeys(rec)
		for _, e in ipairs(hkRows) do e.row:Destroy() end
		table.clear(hkRows)
		hkRec = rec
		local all = hkRow(1, ICON.list, "All Hotkeys")
		on(all.row.Activated, function()
			hkPop:hide()
			openAll(hkAt)
		end)
		for _, b in ipairs(rec.binds) do bindRow(b, false) end
		local add = hkRow(1000, ICON.plusc, "New Hotkey")
		on(add.row.Activated, function()
			local b = newBind(rec)
			listeningBind = b.listener
		end)
		local reset = hkRow(1001, ICON.restore, "Reset", { danger = true })
		on(reset.row.Activated, function()
			hkPop:hide()
			rec.reset()
		end)
		hkAt = (mouseAbs() - overlay.AbsolutePosition) / C.S() + Vector2.new(4, 4)
		hkPop.dir = 1
		hkPop:show(rec.row)
	end

	onFrame(function()
		if not hkPop.open and hkPop.alpha.x >= 0.995 then return end
		local total, w = 8, 0
		for _, e in ipairs(hkRows) do
			total += round(e.h.x)
			w = math.max(w, textWidth(e.label.Text ~= "" and e.label.Text or "None", 12, Enum.Font.BuilderSans))
		end
		hkPop.w = math.max(110, round(31 + w + 16))
		hkPop.h:snap(total)
		hkPop:place(hkAt.X, hkAt.Y, total)
	end)

	---------------- all hotkeys list
	local allList = new("ScrollingFrame", {
		BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollBarThickness = 3, ScrollBarImageColor3 = C.faint,
		ScrollingDirection = Enum.ScrollingDirection.Y, Parent = allPop.inner,
	}, {
		new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2) }),
		new("UIPadding", { PaddingTop = UDim.new(0, 4), PaddingBottom = UDim.new(0, 4), PaddingLeft = UDim.new(0, 4), PaddingRight = UDim.new(0, 4) }),
	})
	local allEmpty = label({ Text = "No hotkeys", TextColor3 = C.faint, TextXAlignment = Enum.TextXAlignment.Center, Size = UDim2.fromScale(1, 1), Visible = false, Parent = allPop.inner })
	local allRows = {}
	local renderAll
	renderAll = function()
		for _, r in ipairs(allRows) do r:Destroy() end
		table.clear(allRows)
		local nameW, keyW = 60, 30
		for _, b in ipairs(hotkeys) do
			local rec = functions[b.fn]
			nameW = math.max(nameW, textWidth(rec and rec.text or b.fn, 12, Enum.Font.BuilderSans))
			keyW = math.max(keyW, textWidth(b.key and keyName(b.key) or "None", 12, Enum.Font.BuilderSansMedium))
		end
		nameW, keyW = math.min(nameW, 180), math.min(keyW, 90)
		for i, b in ipairs(hotkeys) do
			local rec = functions[b.fn]
			local r = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 28), LayoutOrder = i, Parent = allList })
			label({ Text = rec and rec.text or b.fn, TextTruncate = Enum.TextTruncate.AtEnd, Position = UDim2.fromOffset(8, 0), Size = UDim2.fromOffset(nameW, 28), Parent = r })
			label({
				Text = b.key and keyName(b.key) or "None", Font = Enum.Font.BuilderSansMedium, TextColor3 = b.key and C.text or C.dim,
				Position = UDim2.fromOffset(8 + nameW + 16, 0), Size = UDim2.fromOffset(keyW, 28), Parent = r,
			})
			label({ Text = b.mode, TextSize = 11, TextColor3 = C.dim, Position = UDim2.fromOffset(8 + nameW + 16 + keyW + 12, 0), Size = UDim2.fromOffset(40, 28), Parent = r })
			local del, delI, delS = iconButton(ICON.trash, 13, { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -2, 0.5, 0), Size = UDim2.fromOffset(24, 24), Parent = r })
			onFrame(function()
				if not del.Parent then return true end
				del.BackgroundTransparency = 1 - 0.06 * delS.hover.x
				delI.ImageColor3 = C.dim:Lerp(C.danger, delS.hover.x)
			end)
			on(del.Activated, function()
				removeBind(b)
				renderAll()
			end)
			allRows[i] = r
		end
		allEmpty.Visible = #hotkeys == 0
		allPop.w = #hotkeys > 0 and (8 + nameW + 16 + keyW + 12 + 40 + 32 + 8) or 140
		allPop.h.t = #hotkeys > 0 and math.min(8 + #hotkeys * 30, 248) or 44
	end
	openAll = function(at)
		renderAll()
		allPop.h:snap(allPop.h.t)
		allPop.dir = 1
		allPop:place(at.X, at.Y, allPop.h.t)
		allPop:show(nil)
	end

	---------------- wiring
	attachHotkeys = function(rec)
		on(rec.row.MouseButton2Click, function() openHotkeys(rec) end)
	end

	hotkeyInput = function(input, began)
		for _, b in ipairs(hotkeys) do
			if b.key and listeningBind ~= b.listener and matchesKey(input, b.key) then
				if b.mode == "Hold" then
					b.active = began
				elseif began then
					b.active = not b.active
				end
			end
		end
	end

	options.hotkeys = {
		save = function()
			local t = {}
			for _, b in ipairs(hotkeys) do
				t[#t + 1] = { fn = b.fn, key = b.key or false, mode = b.mode, value = b.value }
			end
			return t
		end,
		load = function(t)
			if type(t) ~= "table" then return end
			for i = #hotkeys, 1, -1 do removeBind(hotkeys[i]) end
			for _, d in ipairs(t) do
				local rec = type(d) == "table" and functions[d.fn]
				if rec then
					newBind(rec, {
						key = validKey(d.key) and { kind = d.key.kind, name = d.key.name } or nil,
						mode = d.mode == "Hold" and "Hold" or "Toggle",
						value = d.value == true,
					})
				end
			end
		end,
	}
end

local function colorOption(id, cv)
	options[id] = {
		save = function() return hex8(cv) end,
		load = function(t)
			local c, a = parseHex(tostring(t))
			if c then cv:setRGB(c, a or 1) end
		end,
	}
end

-- Square color swatch; several colors show as a diagonal gradient. Left click opens the picker,
-- right click copies/pastes.
local function swatch(parent, target, rightInset)
	local list = target.dh and { { cv = target } } or target
	local b = button({ AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -rightInset, 0.5, 0), Size = UDim2.fromOffset(18, 18), Parent = parent })
	local sc = new("UIScale", { Parent = b })
	corner(5).Parent = checker(b, { Size = UDim2.fromScale(1, 1) })
	local grad = new("UIGradient", { Rotation = 45 })
	new("Frame", { BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), Parent = b }, { corner(5), grad })
	local s = new("UIStroke", { Color = C.fieldStroke, Thickness = 1, Parent = b })
	corner(5).Parent = b
	local st = hoverable(b)
	on(b.Activated, function() openPicker(target, b) end)
	on(b.MouseButton2Click, function() colorMenu(target, b) end)
	onFrame(function()
		if not b.Parent then return true end
		local n = #list
		local ck, tk = {}, {}
		for i, e in ipairs(list) do
			local pos = n == 1 and 0 or (i - 1) / (n - 1)
			ck[#ck + 1] = ColorSequenceKeypoint.new(pos, e.cv:display())
			tk[#tk + 1] = NumberSequenceKeypoint.new(pos, 1 - e.cv.da.x)
		end
		if n == 1 then
			ck[2] = ColorSequenceKeypoint.new(1, ck[1].Value)
			tk[2] = NumberSequenceKeypoint.new(1, tk[1].Value)
		end
		grad.Color = ColorSequence.new(ck)
		grad.Transparency = NumberSequence.new(tk)
		local active = picker.open and pickTarget == target and 1 or 0
		s.Color = C.fieldStroke:Lerp(C.dim, st.hover.x):Lerp(C.hi, active * 0.7)
		sc.Scale = 1 + st.hover.x * 0.06 - st.press.x * 0.1
	end)
	return b
end

-- Toggle row, optionally with color swatch(es) next to the switch: color is a Color3 or a list of
-- { name, Color3 }. Returns getter, ColorValue (or list of { name, cv }).
-- Right click the row for hotkeys. An active bind overrides the value: it forces the function on,
-- or off when the bind's Value is set; when the bind releases, the function returns to its own state.
local function toggleControl(box, id, text, default, color)
	local rec = { id = id, text = text, default = default and true or false, binds = {} }
	rec.base = rec.default
	functions[id] = rec
	function rec.get()
		if rec.locked and rec.locked() then return false end
		local v = rec.base
		for _, b in ipairs(rec.binds) do
			if b.active then v = not b.value end
		end
		return v
	end
	function rec.set(v)
		rec.base = v
		for _, b in ipairs(rec.binds) do b.active = false end
	end
	function rec.reset() rec.set(rec.default) end
	options[id] = {
		save = function() return rec.base end,
		load = function(v) if type(v) == "boolean" then rec.set(v) end end,
	}

	local r, setRight, rowSt = itemRow(box, text)
	rec.row, rec.box, rec.order, rec.setRight = r, box, r.LayoutOrder, setRight
	attachHotkeys(rec)
	setRight(color and 74 or 46)
	local cv
	if typeof(color) == "Color3" then
		cv = colorValue(color, 1)
		colorOption(id .. ".color", cv)
	elseif color then
		cv = {}
		for i, c in ipairs(color) do
			cv[i] = { name = c[1], cv = colorValue(c[2], 1) }
			colorOption(id .. ".color." .. c[1], cv[i].cv)
		end
	end
	if cv then swatch(r, cv, 56) end
	local track = new("Frame", {
		BorderSizePixel = 0, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -14, 0.5, 0), Size = UDim2.fromOffset(34, 20), Parent = r,
	}, { new("UICorner", { CornerRadius = UDim.new(1, 0) }) })
	local knob = new("Frame", {
		BorderSizePixel = 0, AnchorPoint = Vector2.new(0, 0.5), Size = UDim2.fromOffset(14, 14), Parent = track,
	}, { new("UICorner", { CornerRadius = UDim.new(1, 0) }) })
	local onS = spring(rec.base and 1 or 0, 24)
	on(r.Activated, function()
		if rec.locked and rec.locked() then
			if C.onLocked then C.onLocked(rec) end
			return
		end
		rec.set(not rec.get())
	end)
	onFrame(function()
		onS.t = rec.get() and 1 or 0
		local a = onS.x
		local press = rowSt.press.x
		track.BackgroundColor3 = C.toggleOff:Lerp(C.fieldStroke, rowSt.hover.x * (1 - a) * 0.6):Lerp(accent, a)
		knob.BackgroundColor3 = C.knobOff:Lerp(Color3.new(1, 1, 1), a)
		-- the knob stretches while pressed and slides with the spring
		local kw = 14 + 4 * press
		knob.Size = UDim2.fromOffset(round(kw), 14)
		knob.Position = UDim2.new(0, round(3 + a * (34 - 6 - kw)), 0.5, 0)
	end)
	return rec.get, cv
end

local function multiDropdown(box, id, text, items)
	local chosen = {}
	options[id] = {
		save = function()
			local t = {}
			for _, it in ipairs(items) do if chosen[it] then t[#t + 1] = it end end
			return t
		end,
		load = function(t)
			if type(t) ~= "table" then return end
			table.clear(chosen)
			for _, it in ipairs(t) do chosen[it] = true end
		end,
	}
	local W = 150
	local r, setRight = itemRow(box, text)
	setRight(W + 8)
	local b, s, sc = fieldButton({ AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -12, 0.5, 0), Size = UDim2.fromOffset(W, 26), Parent = r })
	local lbl = label({ Text = "None", TextTruncate = Enum.TextTruncate.AtEnd, Position = UDim2.fromOffset(10, 0), Size = UDim2.new(1, -30, 1, 0), Parent = b })
	local chev = icon(ICON.chevron, 11, { Position = UDim2.new(1, -13, 0.5, 0), ImageColor3 = C.dim, Parent = b })
	local st = hoverable(b)

	local IT_H = 28
	local pop = Popup.new(W, 8 + #items * IT_H)
	for i, it in ipairs(items) do
		local row = button({ Position = UDim2.fromOffset(4, 4 + (i - 1) * IT_H), Size = UDim2.new(1, -8, 0, IT_H), Parent = pop.inner }, { corner(5) })
		local t = label({ Text = it, TextTruncate = Enum.TextTruncate.AtEnd, Position = UDim2.fromOffset(9, 0), Size = UDim2.new(1, -36, 1, 0), Parent = row })
		local ck = icon(ICON.check, 14, { Position = UDim2.new(1, -14, 0.5, 0), Parent = row })
		bindAccent(ck, function(c) ck.ImageColor3 = c end)
		local rst = hoverable(row)
		local onS = spring(0, 28)
		on(row.Activated, function() chosen[it] = not chosen[it] or nil end)
		onFrame(function()
			onS.t = chosen[it] and 1 or 0
			row.BackgroundTransparency = 1 - 0.05 * rst.hover.x
			t.TextColor3 = C.text:Lerp(C.hi, math.max(rst.hover.x, onS.x))
			ck.ImageTransparency = 1 - onS.x
			ck.Size = UDim2.fromOffset(14 * (0.5 + 0.5 * onS.x), 14 * (0.5 + 0.5 * onS.x))
		end)
	end

	on(b.Activated, function()
		if pop.open then
			pop:hide()
		else
			local h = 8 + #items * IT_H
			pop.h:snap(h)
			pop:placeAt(b, h, true)
			pop:show(b)
		end
	end)
	onFrame(function()
		local names = {}
		for _, it in ipairs(items) do if chosen[it] then names[#names + 1] = it end end
		local s2 = #names > 0 and table.concat(names, ", ") or "None"
		C.setText(lbl, s2)
		lbl.TextColor3 = #names > 0 and C.text or C.dim
		local openA = 1 - pop.alpha.x
		b.BackgroundColor3 = C.field:Lerp(C.fieldHover, math.max(st.hover.x, openA) * 0.7)
		s.Color = C.fieldStroke:Lerp(C.dim, math.max(st.hover.x * 0.4, openA * 0.5))
		sc.Scale = 1 - st.press.x * 0.03
		chev.Rotation = 180 * openA
		chev.ImageColor3 = C.dim:Lerp(C.hi, st.hover.x)
	end)
	return chosen
end

local function keybindControl(box, text, get, set)
	local r, setRight = itemRow(box, text)
	local b, s, sc = fieldButton({ AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -12, 0.5, 0), Size = UDim2.fromOffset(60, 24), Parent = r })
	local lbl = label({ Text = "", Font = Enum.Font.BuilderSansMedium, TextXAlignment = Enum.TextXAlignment.Center, Size = UDim2.fromScale(1, 1), Parent = b })
	local st = hoverable(b)
	local w = spring(60, 30, 0.01)
	local listen = spring(0, 22, 1e-3)
	local state = { capturedAt = 0 }
	function state.capture(k)
		set(k)
		listeningBind = nil
		state.capturedAt = os.clock()
	end
	on(b.Activated, function()
		-- The click that bound Mouse 1 also lands here; don't re-arm on it.
		if os.clock() - state.capturedAt < 0.4 or listeningBind == state then return end
