-- Fades the given toggle rows while active() is false: they only matter when the master switch is on.
function dimRows(ids, active)
	local items = {}
	for _, id in ipairs(ids) do
		local row = functions[id].row
		for _, o in ipairs(row:GetDescendants()) do
			if o:IsA("TextLabel") then items[#items + 1] = { o, "TextTransparency" }
			elseif o:IsA("ImageLabel") or o:IsA("ImageButton") then items[#items + 1] = { o, "ImageTransparency" }
			elseif o:IsA("Frame") and o.BackgroundTransparency < 1 and o.Size.Y.Offset ~= 1 then items[#items + 1] = { o, "BackgroundTransparency" } end
		end
	end
	local k = spring(active() and 0 or 1, 18, 1e-3)
	onFrame(function()
		k.t = active() and 0 or 1
		local v = k.x * 0.55
		for _, it in ipairs(items) do
			if it[1][it[2]] ~= v then it[1][it[2]] = v end
		end
	end)
end

-- One compact row of numbers with captions under them, e.g. Caught / Perfect / Lost.
function statsRow(box, captions)
	local n = boxRows[box] or 0
	boxRows[box] = n + 1
	local r = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 54), LayoutOrder = (n + 1) * 100, Parent = box })
	if n > 0 then new("Frame", { BackgroundColor3 = C.rowLine, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 1), Parent = r }) end
	local setters = {}
	for i, cap in ipairs(captions) do
		local col = new("Frame", { BackgroundTransparency = 1, Position = UDim2.fromScale((i - 1) / #captions, 0), Size = UDim2.new(1 / #captions, 0, 1, 0), Parent = r })
		local v = label({ Text = "0", Font = Enum.Font.BuilderSansMedium, TextSize = 17, TextColor3 = C.hi, TextXAlignment = Enum.TextXAlignment.Center, Position = UDim2.fromOffset(0, 9), Size = UDim2.new(1, 0, 0, 20), Parent = col })
		label({ Text = cap, TextSize = 11, TextColor3 = C.dim, TextXAlignment = Enum.TextXAlignment.Center, Position = UDim2.fromOffset(0, 31), Size = UDim2.new(1, 0, 0, 14), Parent = col })
		if i > 1 then new("Frame", { BackgroundColor3 = C.rowLine, BorderSizePixel = 0, Position = UDim2.new(0, 0, 0, 12), Size = UDim2.new(0, 1, 1, -24), Parent = col }) end
		setters[i] = function(t) C.setText(v, t) end
	end
	return setters
end

-- A searchable list living inside a group box. getItems() returns { { key, text, sub, color, action } }.
function pickList(box, getItems, searchable, height, empty, locked)
	local n = boxRows[box] or 0
	boxRows[box] = n + 1
	local top = searchable and 44 or 4
	local wrap = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, height + top + 6), LayoutOrder = (n + 1) * 100, Parent = box })
	if n > 0 then new("Frame", { BackgroundColor3 = C.rowLine, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 1), Parent = wrap }) end
	local q = new("TextBox", { Text = "" })
	if searchable then
		local field = new("Frame", { BackgroundColor3 = C.field, BorderSizePixel = 0, Position = UDim2.fromOffset(10, 8), Size = UDim2.new(1, -20, 0, 30), Parent = wrap }, { corner(6) })
		stroke(C.fieldStroke, field)
		icon(ICON.search, 14, { Position = UDim2.fromOffset(16, 15), ImageColor3 = C.faint, Parent = field })
		q = new("TextBox", {
			Text = "", PlaceholderText = "Search", PlaceholderColor3 = C.faint, ClearTextOnFocus = false,
			Font = Enum.Font.BuilderSans, TextSize = 13, TextColor3 = C.hi, TextXAlignment = Enum.TextXAlignment.Left,
			BackgroundTransparency = 1, Position = UDim2.fromOffset(31, 0), Size = UDim2.new(1, -38, 1, 0), Parent = field,
		})
	end
	local list = new("ScrollingFrame", {
		BackgroundTransparency = 1, BorderSizePixel = 0, Position = UDim2.fromOffset(0, top), Size = UDim2.new(1, 0, 0, height),
		CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollBarThickness = 2, ScrollBarImageColor3 = C.faint,
		ScrollingDirection = Enum.ScrollingDirection.Y, Parent = wrap,
	}, {
		new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2) }),
		new("UIPadding", { PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 8), PaddingTop = UDim.new(0, 2) }),
	})
	local emptyLbl = label({ Text = empty or "Nothing here", TextColor3 = C.faint, TextXAlignment = Enum.TextXAlignment.Center, Size = UDim2.new(1, 0, 0, 30), Position = UDim2.fromOffset(0, top), Parent = wrap })
	local rows = {}
	local function row(i)
		local r = rows[i]
		if r then return r end
		local b = button({ Size = UDim2.new(1, 0, 0, 30), LayoutOrder = i, Parent = list }, { corner(6) })
		local t = label({ TextSize = 13, Position = UDim2.fromOffset(10, 0), Size = UDim2.new(1, -120, 1, 0), TextTruncate = Enum.TextTruncate.AtEnd, Parent = b })
		local s = label({ TextSize = 12, TextColor3 = C.faint, TextXAlignment = Enum.TextXAlignment.Right, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -10, 0, 0), Size = UDim2.new(0, 104, 1, 0), Parent = b })
		local lk = icon(ICON.lock, 12, { Position = UDim2.new(1, -18, 0.5, 0), ImageColor3 = C.dim, Visible = false, Parent = b })
		local dot = new("Frame", { BorderSizePixel = 0, AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 10, 0.5, 0), Size = UDim2.fromOffset(7, 7), Visible = false, Parent = b }, { new("UICorner", { CornerRadius = UDim.new(1, 0) }) })
		r = { b = b, t = t, s = s, lk = lk, dot = dot, st = hoverable(b) }
		on(b.Activated, function()
			if not (r.item and r.item.action) or r.item.header then return end
			if locked and locked() then Fisch.locked() return end
			task.spawn(r.item.action)
		end)
		rows[i] = r
		return r
	end
	local nextAt, lastQ = 0, nil
	onFrame(function()
		if not wrap.Parent then return true end
		local isLocked = locked ~= nil and locked()
		for _, r in ipairs(rows) do
			if r.b.Visible and r.item.header then
				r.lk.Visible = false
				r.b.BackgroundTransparency = 1
				r.t.TextColor3 = r.item.color or C.section
			elseif r.b.Visible then
				r.lk.Visible = isLocked
				r.s.Visible = not isLocked
				r.t.TextTransparency = isLocked and 0.45 or 0
				r.b.BackgroundTransparency = 1 - 0.05 * r.st.hover.x
				r.t.TextColor3 = (r.item.color or C.text):Lerp(C.hi, r.st.hover.x * 0.5)
			end
		end
		if os.clock() < nextAt and q.Text == lastQ then return end
		nextAt, lastQ = os.clock() + 0.5, q.Text
		local query = q.Text:lower()
		local ok, items = pcall(getItems)
		if not ok then items = {} end
		local k = 0
		for _, it in ipairs(items) do
			if it.header or query == "" or it.text:lower():find(query, 1, true) then
				k += 1
				local r = row(k)
				r.item = it
				local hd = it.header == true
				r.t.Font = hd and Enum.Font.BuilderSansBold or Enum.Font.BuilderSans
				r.t.TextSize = hd and 11 or 13
				r.dot.Visible = it.dot ~= nil and not hd
				if it.dot then r.dot.BackgroundColor3 = it.dot end
				r.t.Position = UDim2.fromOffset((it.dot and not hd) and 24 or 10, 0)
				r.b.Size = UDim2.new(1, 0, 0, hd and 24 or 30)
				C.setText(r.t, it.text)
				local sub = it.sub or ""
				C.setText(r.s, sub)
				r.b.Visible = true
			end
		end
		for i = 1, k do
			local r = rows[i]
			if r.item.header and (i == k or rows[i + 1].item.header) then r.b.Visible = false end
		end
		for i = k + 1, #rows do rows[i].b.Visible = false; rows[i].item = nil end
		emptyLbl.Visible = k == 0
	end)
	return wrap
end
end)()

