local Net = require(RS.packages.Net)
local favRemote = Net:RemoteEvent("Backpack/Favourite")

---------------------------------------- inventory + favourites

function Fisch.inventory()
	local ok, inv = pcall(function() return DC.InventoryReplicator:TryIndex({ "Inventory" }) end)
	return ok and type(inv) == "table" and inv or {}
end
function Fisch.isFish(it) return type(it) == "table" and type(it.sub) == "table" and it.sub.Weight ~= nil end
function Fisch.favourite(id, v) favRemote:FireServer(id, v) end
Fisch.rules = {} -- fish name -> min kg (0 = any weight); filled by the Collection page
function Fisch.protects(it)
	local min = Fisch.rules[it.name]
	return min ~= nil and (min <= 0 or (tonumber(it.sub.Weight) or 0) >= min)
end
-- Favourites every fish the rules protect and waits until the server confirms each one.
-- Selling only goes ahead when this returns true.
function Fisch.protectAll(timeout)
	local pending = {}
	for id, it in pairs(Fisch.inventory()) do
		if Fisch.isFish(it) and not it.sub.Favourited and Fisch.protects(it) then
			pending[id] = true
			Fisch.favourite(id, true)
			task.wait(0.12)
		end
	end
	local t0 = os.clock()
	while next(pending) and os.clock() - t0 < (timeout or 4) do
		task.wait(0.2)
		local inv = Fisch.inventory()
		for id in pairs(pending) do
			local it = inv[id]
			if not it or (it.sub and it.sub.Favourited) then pending[id] = nil end
		end
	end
	return next(pending) == nil
end
function Fisch.sellableCount()
	local n = 0
	for _, it in pairs(Fisch.inventory()) do
		if Fisch.isFish(it) and not it.sub.Favourited then n += (tonumber(it.sub.Stack) or 1) end
	end
	return n
end

---------------------------------------- teleport

local platform
local function removePlatform() if platform then platform:Destroy(); platform = nil end end
local function castDown(from, dist)
	local p = RaycastParams.new()
	p.FilterType = Enum.RaycastFilterType.Exclude
	local ignore = { LP.Character }
	if workspace:FindFirstChild("zones") then ignore[#ignore + 1] = workspace.zones end
	if platform then ignore[#ignore + 1] = platform end
	p.FilterDescendantsInstances = ignore
	p.IgnoreWater = false
	return workspace:Raycast(from, Vector3.new(0, -dist, 0), p)
end
-- Teleports onto the ground under pos (searched from `above` studs higher). Lands on water ->
-- stands on a small platform so you can fish right there. exact = no ground search.
-- In Safe Mode teleports are allowed once every 5 s.
function Fisch.tpReady()
	if not Fisch.safe then return true end
	local left = 5 - (os.clock() - (Fisch.lastTp or -1e9))
	if left > 0 then
		toast(string.format("Teleport ready in %d s", math.ceil(left)))
		return false
	end
	return true
end
function Fisch.tp(pos, look, above, exact)
	if not Fisch.tpReady() then return false end
	Fisch.lastTp = os.clock()
	local char = LP.Character
	local hrp = char and char:FindFirstChild("HumanoidRootPart")
	if not hrp then return false end
	pcall(LP.RequestStreamAroundAsync, LP, pos, 3)
	local target, water = pos, false
	if not exact then
		local hit = castDown(pos + Vector3.new(0, above or 300, 0), (above or 300) + 400)
		if hit then
			target = hit.Position
			water = hit.Instance == workspace.Terrain and hit.Material == Enum.Material.Water
		end
	end
	if water then
		removePlatform()
		platform = new("Part", {
			Name = tostring(math.random(1e8, 9e8)), Anchored = true, CanCollide = true, CanQuery = false, CanTouch = false,
			Size = Vector3.new(10, 1, 10), CFrame = CFrame.new(target - Vector3.new(0, 0.3, 0)),
			Material = Enum.Material.SmoothPlastic, Color = Color3.fromRGB(30, 32, 36), Transparency = 0.35, Parent = workspace,
		})
	end
	local p = target + Vector3.new(0, 3.2, 0)
	local cf = look and CFrame.lookAt(p, Vector3.new(look.X, p.Y, look.Z)) or CFrame.new(p) * hrp.CFrame.Rotation
	hrp.AssemblyLinearVelocity = Vector3.zero
	char:PivotTo(cf)
	return true
end
function Fisch.back(cf)
	if not Fisch.tpReady() then return end
	Fisch.lastTp = os.clock()
	local char = LP.Character
	local hrp = char and char:FindFirstChild("HumanoidRootPart")
	if not hrp then return end
	pcall(LP.RequestStreamAroundAsync, LP, cf.Position, 3)
	hrp.AssemblyLinearVelocity = Vector3.zero
	char:PivotTo(cf)
end
Fisch.cleanups[#Fisch.cleanups + 1] = removePlatform

---------------------------------------- NPC registry (live models + remembered positions)

local NPC_FILE = ROOT .. "/npcs.json"
local npcs = {} -- key -> { name, type, x, y, z }
pcall(function()
	local t = HttpService_:JSONDecode(readfile(NPC_FILE))
	if type(t) == "table" then npcs = t end
end)
local live = {} -- key -> model
local function keyOf(name, p) return name .. "@" .. math.floor(p.X / 40) .. "," .. math.floor(p.Z / 40) end
function Fisch.scanNpcs()
	local root = workspace:FindFirstChild("world") and workspace.world:FindFirstChild("npcs")
	if not root then return end
	table.clear(live)
	local changed = false
	for _, m in ipairs(root:GetDescendants()) do
		if m:IsA("Model") and m:FindFirstChildOfClass("Humanoid") then
			local ok, p = pcall(function() return m:GetPivot().Position end)
			if ok then
				local k = keyOf(m.Name, p)
				live[k] = m
				local rec = npcs[k]
				local ty = m:GetAttribute("NpcType")
				if not rec or rec.type ~= ty then
					npcs[k] = { name = m.Name, type = ty, x = p.X, y = p.Y, z = p.Z }
					changed = true
				end
			end
		end
	end
	if changed then pcall(writefile, NPC_FILE, HttpService_:JSONEncode(npcs)) end
end
function Fisch.npcList()
	local out = {}
	for k, rec in pairs(npcs) do
		out[#out + 1] = { key = k, rec = rec, model = live[k] }
	end
	return out
end
function Fisch.npcPos(e)
	if e.model and e.model.Parent then
		local ok, cf = pcall(function() return e.model:GetPivot() end)
		if ok then return cf end
	end
	return CFrame.new(e.rec.x, e.rec.y, e.rec.z)
end
function Fisch.myPos()
	local char = LP.Character
	local hrp = char and char:FindFirstChild("HumanoidRootPart")
	return hrp and hrp.Position
end
function Fisch.nearest(npcType)
	local me = Fisch.myPos()
	if not me then return nil end
	local best, bd
	for _, e in ipairs(Fisch.npcList()) do
		if e.rec.type == npcType then
			local d = (Vector3.new(e.rec.x, e.rec.y, e.rec.z) - me).Magnitude
			if not bd or d < bd then best, bd = e, d end
		end
	end
	return best, bd
end
function Fisch.tpNpc(e)
	local cf = Fisch.npcPos(e)
	local front = (cf * CFrame.new(0, 0, -4)).Position
	return Fisch.tp(front, cf.Position, 6)
end
task.spawn(function()
	while gui.Parent do
		pcall(Fisch.scanNpcs)
		task.wait(5)
	end
end)

---------------------------------------- sell

-- Unequips, makes sure every protected fish is favourited (server-confirmed), sells at the nearest
-- merchant through the game's own Sell All, and puts you back exactly where you stood.
function Fisch.sell()
	if Fisch.safe then return false, "Safe Mode" end
	if Fisch.busy then return false, "busy" end
	Fisch.busy = true
	local ok, err = pcall(function()
		local char = LP.Character
		local hrp = char and char:FindFirstChild("HumanoidRootPart")
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		if not (hrp and hum) then error("no character") end
		if not Fisch.protectAll(5) then error("favourites not confirmed, sale skipped") end
		local m = Fisch.nearest("Merchant")
		if not m then error("no merchant known yet") end
		local back = hrp.CFrame
		hum:UnequipTools()
		task.wait(0.3)
		Fisch.tpNpc(m)
		task.wait(0.9)
		local res = RS.events.SellAll:InvokeServer()
		task.wait(0.4)
		Fisch.back(back)
		task.wait(0.4)
		if res == false and Fisch.sellableCount() > 0 then error("merchant refused") end
	end)
	Fisch.busy = false
	return ok, err
end

