local noteHost = new("Frame", {
	BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -16, 0, 70),
	Size = UDim2.fromOffset(300, 420), ZIndex = 200, Parent = gui,
}, { new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder }) })
local noteN = 0
-- Card with up to two buttons (the first is the main one, accent colored); a thin bar along the
-- bottom shows how long it stays.
function Fisch.notify(title, text, actionText, action, ttl, action2Text, action2)
	noteN += 1
	ttl = ttl or 25
	local btns = {}
	if actionText then btns[#btns + 1] = { actionText, action, true } end
	if action2Text then btns[#btns + 1] = { action2Text, action2, false } end
	local textW = 16 + #btns * 72 + 8
	local card = new("CanvasGroup", {
		BackgroundColor3 = C.popup, BorderSizePixel = 0, Size = UDim2.fromOffset(300, 64), GroupTransparency = 1,
		LayoutOrder = -noteN, ZIndex = 200, Parent = noteHost,
	}, { corner(10) })
	stroke(C.popupStroke, card)
	local bar = new("Frame", { BorderSizePixel = 0, Size = UDim2.new(0, 3, 1, 0), ZIndex = 201, Parent = card })
	bindAccent(bar, function(c) bar.BackgroundColor3 = c end)
	local timeBar = new("Frame", { BorderSizePixel = 0, BackgroundTransparency = 0.5, Position = UDim2.new(0, 3, 1, -2), Size = UDim2.new(1, -3, 0, 2), ZIndex = 201, Parent = card })
	bindAccent(timeBar, function(c) timeBar.BackgroundColor3 = c end)
	label({ Text = title, Font = Enum.Font.BuilderSansMedium, TextSize = 13, TextColor3 = C.hi, Position = UDim2.fromOffset(16, 11), Size = UDim2.new(1, -textW, 0, 16), TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 201, Parent = card })
	label({ Text = text, TextSize = 12, TextColor3 = C.dim, Position = UDim2.fromOffset(16, 33), Size = UDim2.new(1, -textW, 0, 16), TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 201, Parent = card })
	local a = spring(0, 18, 1e-3)
	a.t = 1
	local dead = false
	local function close() dead = true; a.t = 0 end
	for i, def in ipairs(btns) do
		local x = -12 - (#btns - i) * 72
		local b, s, sc = fieldButton({ AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, x, 0.5, 0), Size = UDim2.fromOffset(64, 28), ZIndex = 201, Parent = card })
		local bl = label({ Text = def[1], Font = Enum.Font.BuilderSansMedium, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Center, Size = UDim2.fromScale(1, 1), ZIndex = 202, Parent = b })
		if def[3] then
			bindAccent(bl, function(c) bl.TextColor3 = c:Lerp(Color3.new(1, 1, 1), 0.3) end)
		else
			bl.TextColor3 = C.dim
		end
		local st = hoverable(b)
		on(b.Activated, function()
			if dead then return end
			if def[2] then task.spawn(def[2]) end
			close()
		end)
		onFrame(function()
			if not b.Parent then return true end
			b.BackgroundColor3 = C.field:Lerp(C.fieldHover, st.hover.x)
			sc.Scale = 1 - st.press.x * 0.04
		end, true)
	end
	local born = os.clock()
	onFrame(function()
		local left = 1 - (os.clock() - born) / ttl
		if left <= 0 then close() end
		timeBar.Size = UDim2.new(math.max(left, 0), -3, 0, 2)
		card.GroupTransparency = 1 - a.x
		if dead and a.x < 0.01 then card:Destroy(); return true end
	end, true)
	return close
end
end)()


