---------------------------------------- game state

local S = { caught = 0, perfect = 0, lost = 0, status = "Idle", nextCast = 0, holding = false, pressedDir = false,
	aimOff = 0, aimUntil = 0, lastPerfect = false }

local function rodTool()
	local char = LP.Character
	local t = char and char:FindFirstChildOfClass("Tool")
	if t and t:FindFirstChild("rodClient") and t:FindFirstChild("values") then return t, true end
	local bp = LP:FindFirstChild("Backpack")
	if not bp then return nil end
	local want = LP:GetAttribute("CurrentRod")
	local pick = want and bp:FindFirstChild(want)
	if pick and pick:FindFirstChild("rodClient") then return pick, false end
	for _, c in ipairs(bp:GetChildren()) do
		if c:IsA("Tool") and c:FindFirstChild("rodClient") then return c, false end
	end
end

local function reeling()
	local char = LP.Character
	return char ~= nil and char:GetAttribute("ReelActive") ~= nil
end

-- A spot on the screen with nothing of the game's UI and not our window under it, for the cast click.
local function clickPoint()
	local cam = workspace.CurrentCamera
	local vp = cam and cam.ViewportSize or Vector2.new(1280, 720)
	local inset = GuiService:GetGuiInset()
	local pg = LP:FindFirstChild("PlayerGui")
	for _, f in ipairs({ { 0.5, 0.42 }, { 0.3, 0.35 }, { 0.7, 0.35 }, { 0.5, 0.25 }, { 0.2, 0.55 }, { 0.8, 0.55 } }) do
		local p = Vector2.new(round(vp.X * f[1]), round(vp.Y * f[2]))
		local overMenu = holder.Visible and inside(window, p + probe.AbsolutePosition)
		local overGui = false
		if pg then
			for _, o in ipairs(pg:GetGuiObjectsAtPosition(p.X, p.Y - inset.Y)) do
				if o.Active and o.Visible then overGui = true break end
			end
		end
		if not overMenu and not overGui then return p end
	end
	return Vector2.new(round(vp.X * 0.5), round(vp.Y * 0.42))
end

local function mouse(down, p)
	VIM:SendMouseButtonEvent(p.X, p.Y, 0, down, game, 0)
end

local function powerOf(char)
	for _, n in ipairs({ "power", "thunderpower" }) do
		local g_ = char:FindFirstChild(n, true)
		local bar = g_ and g_:FindFirstChild("powerbar")
		bar = bar and bar:FindFirstChild("bar")
		if bar then return n == "thunderpower" and 1 or bar.Size.Y.Scale end
	end
end

-- Auto water aim: if you're not facing water, turn to the closest direction that has open water
-- 12..30 studs out (where a cast lands), so the bobber always goes in.
local aimParams = RaycastParams.new()
aimParams.FilterType = Enum.RaycastFilterType.Exclude
aimParams.IgnoreWater = false
local function waterAt(p)
	local hit = workspace:Raycast(p + Vector3.new(0, 40, 0), Vector3.new(0, -120, 0), aimParams)
	return hit and hit.Instance == workspace.Terrain and hit.Material == Enum.Material.Water
end
local function aimAtWater()
	local char = LP.Character
	local hrp = char and char:FindFirstChild("HumanoidRootPart")
	if not hrp then return end
	local ignore = { char }
	if workspace:FindFirstChild("zones") then ignore[2] = workspace.zones end
	aimParams.FilterDescendantsInstances = ignore
	local look = hrp.CFrame.LookVector
	local base = math.atan2(-look.X, -look.Z)
	for step = 0, 12 do
		for _, sign in ipairs(step == 0 and { 1 } or { 1, -1 }) do
			local ang = base + sign * step * math.rad(15)
			local dir = Vector3.new(-math.sin(ang), 0, -math.cos(ang))
			local hits = 0
			for _, d in ipairs({ 12, 18, 24, 30 }) do
				if waterAt(hrp.Position + dir * d) then hits += 1 end
			end
			if hits >= 3 then
				if step > 0 then
					local p = hrp.Position
					hrp.CFrame = CFrame.lookAt(p, p + dir)
					task.wait(0.08)
				end
				return true
			end
		end
	end
	return false
end

-- Hold the button, let the game's power meter climb, release at the top: the game itself
-- grades it (perfect cast = above ~92%).
local function cast(tool)
	local char = LP.Character
	if not char then return end
	local p = clickPoint()
	local random = castMode() == "Random"
	local goal = random and (0.55 + math.random() * 0.4) or 0.95
	S.status = "Casting"
	S.holding = p
	mouse(true, p)
	local t0, last, charged = os.clock(), -1, false
	while os.clock() - t0 < 4 and autoOn() and castOn() and tool.Parent == char do
		task.wait()
		local pw = powerOf(char)
		if pw then
			charged = true
			if pw >= goal or (not random and last >= 0.88 and pw < last) then break end
			last = pw
		elseif charged or os.clock() - t0 > 0.6 then
			break -- the game didn't start charging (cooldown, blocked): let go and retry soon
		end
	end
	mouse(false, p)
	S.holding = false
	return charged
end

---------------------------------------- main loop

local alive = true
local loop = task.spawn(function()
	while alive do
		local waitFor = 0.05
		local ok, err = pcall(function()
			if not autoOn() then
				S.status = "Off"
				return
			end
			if Fisch.busy then
				S.status = "Busy"
				return
			end
			local char = LP.Character
			local hum = char and char:FindFirstChildOfClass("Humanoid")
			if not hum or hum.Health <= 0 then
				S.status = "Dead"
				return
			end
			if reeling() then
				S.status = "Reeling"
				S.nextCast = os.clock() + recastDelay() / 1000 + math.random() * 0.25
				return
			end
			local pg = LP:FindFirstChild("PlayerGui")
			local shake = pg and pg:FindFirstChild("shakeui")
			if shake and shake.Enabled then
				S.status = "Shaking"
				if shakeOn() then
					-- the game binds Enter to the shake button (keyboard / gamepad path), throttled to 0.25 s
					VIM:SendKeyEvent(true, Enum.KeyCode.Return, false, game)
					task.wait(0.02 + math.random() * 0.02)
					VIM:SendKeyEvent(false, Enum.KeyCode.Return, false, game)
					waitFor = 0.26 + shakeDelay() / 1000 + math.random() * 0.04
				end
				return
			end
			local tool, equipped = rodTool()
			if not tool then
				S.status = "No rod"
				return
			end
			if not equipped then
				S.status = "Equipping"
				if equipOn() and hum:GetState() ~= Enum.HumanoidStateType.Swimming then
					hum:EquipTool(tool)
					waitFor = 0.8
				end
				return
			end
			local v = tool.values
			if v.casted.Value or v.state.Value > 3 then
				S.status = v.state.Value == 6 and "Waiting for bite" or "Fishing"
				return
			end
			S.status = "Ready"
			-- sell between casts, never mid-fish
			if sellOn() and os.clock() >= (S.sellRetry or 0) and Fisch.sellableCount() >= sellAt() then
				S.status = "Selling"
				local ok, e = Fisch.sell()
				if not ok then
					S.sellRetry = os.clock() + 60
					toast("Auto sell: " .. tostring(e))
				end
				waitFor = 0.6
				return
			end
			if LP:GetAttribute("RodEquipInProgress") or LP:GetAttribute("BlockCast") then return end
			if castOn() and os.clock() >= S.nextCast and hum:GetState() ~= Enum.HumanoidStateType.Swimming then
				if waterAimOn() then pcall(aimAtWater) end
				if cast(tool) then
					S.nextCast = os.clock() + 2.5 -- the throw takes a moment to register as casted
				else
					S.nextCast = os.clock() + 0.6 + math.random() * 0.3
				end
				waitFor = 0.3
			end
		end)
		if not ok then warn("[FischMenu] " .. tostring(err)) end
		task.wait(waitFor)
	end
end)

---------------------------------------- reel: predictive bang-bang on the game's own bar physics

-- Rolls the game's own bar (RodMovement.Tick) and fish (FishMovement.Tick) forward for H seconds:
-- the button held (d0 = 1) or released (d0 = -1) until tSwitch, then the other way. Trying several
-- switch moments is what lets it brake in time, which tiny bars need. Returns how far the fish strays.
local function rollout(r, rod, fish, d0, tSwitch, H, dt, aim)
	local bp, vel, acc = r.barPosition, rod.CurrentVelocity, rod.CurrentAcceleration
	local dir = d0
	if dir ~= rod.CurrentInputDirection and rod.SimulateLegacyPhysics then acc = 0 end
	local half = r.barSize / 2
	local lo, hi = r.minBarPosition + half, r.maxBarPosition - half
	local accel = r.accel
	local spd = r.barMoveSpeed * math.clamp(accel, -1, 1) * 1.5
	local smoothT = math.clamp(0.85 / math.sqrt(math.abs(accel)), -1e6, 1e6)
	local maxA, elast = rod.MaxAcceleration, rod.BarElasticity
	local fp, fv = r.fishPosition, fish.CurrentVelocity or 0
	local ft, fmt, fms = fish.CurrentTarget, fish.CurrentMoveTime, fish.CurrentMaxSpeed
	local fdt = dt / math.max(r.movementfactor or 1, 1e-3)
	local fishMoves = ft and fmt and fms and not fish.Disabled and not fish.MovementPaused and not (r.frozenUntil > tick())
	local n = math.max(2, math.floor(H / dt + 0.5))
	local cost = 0
	for i = 1, n do
		if dir == d0 and i * dt > tSwitch then
			dir = -d0
			if rod.SimulateLegacyPhysics then acc = 0 end
		end
		local target = dir * spd
		if (bp <= lo and target < 0) or (bp >= hi and target > 0) then target = 0 end
		vel, acc = TS:SmoothDamp(vel, target, acc, smoothT, maxA, dt)
		bp += vel * dt
		if bp <= lo then
			bp = lo
			if vel < 0 then vel *= -elast end
		elseif bp >= hi then
			bp = hi
			if vel > 0 then vel *= -elast end
		end
		if fishMoves then
			fp, fv = TS:SmoothDamp(fp, ft, fv, fmt, fms, fdt)
			fp = math.clamp(fp, 0, 1)
		end
		local e = (fp + aim) - bp
		-- leaving the bar costs far more than being off-center inside it
		local out = math.max(math.abs(e) - half * 0.8, 0)
		cost += (e * e + out * out * 40) * (0.5 + i / n)
	end
	return cost
end

local SWITCH_AT = { 0.05, 0.1, 0.16, 0.24, 0.34, math.huge }
local function setDir(rod, dir)
	if rod.CurrentInputDirection == dir then return end
	if dir == 1 then rod:InputBegan(nil) else rod:InputEnded(nil) end
	S.pressedDir = dir == 1
end

RunService:BindToRenderStep(REEL_STEP, Enum.RenderPriority.Input.Value, function(dt)
	local r = Reel.ActiveReel
	if not r then return end
	if r.active then S.lastPerfect = r.perfect end
	local core = r.core
	local rod, fish = core and core.rod, core and core.fish
	if not (rod and fish) then return end
	if not (autoOn() and reelOn()) then
		if S.pressedDir then pcall(setDir, rod, -1) end
		return
	end
	if not r.active or r.isPaused or rod.Disabled or rod.Paused then return end
	if r.barSize >= r.maxBarPosition - r.minBarPosition then return end
	local ok = pcall(function()
		local mult = LP:GetAttribute("MinigameSpeedMulti") or 1
		local step = math.clamp(dt * mult, 1 / 240, 1 / 20)
		if reelMode() == "Rage" then
			-- The bar is pinned onto the fish every frame and given the fish's own velocity, so the game's
			-- bar tick moves it along with the fish: it can't leave the bar, whatever the rod. The bar never
			-- goes to the server, only the result does, and progress still builds at the normal rate.
			local half = r.barSize / 2
			local lo, hi = r.minBarPosition + half, r.maxBarPosition - half
			local fv = fish.CurrentVelocity or 0
			local want = math.clamp(r.fishPosition + fv * step, lo, hi)
			setDir(rod, fv >= 0 and 1 or -1)
			r.barPosition = want
			rod.CurrentVelocity = fv
			rod.CurrentAcceleration = 0
			return
		end
		local aim = 0
		if reelMode() == "Legit" then
			-- drift around inside the bar instead of pinning the fish dead center
			if os.clock() > S.aimUntil then
				S.aimOff = (math.random() * 2 - 1) * r.barSize * 0.28
				S.aimUntil = os.clock() + 0.5 + math.random() * 0.9
			end
			aim = S.aimOff
		end
		local H = math.max(lookahead() / 1000, 0.45)
		local simDt = 1 / 30
		local best, bestDir = math.huge, -1
		for _, d0 in ipairs({ 1, -1 }) do
			for _, ts in ipairs(SWITCH_AT) do
				local c = rollout(r, rod, fish, d0, ts, H, simDt, aim)
				if c < best then best, bestDir = c, d0 end
			end
		end
		setDir(rod, bestDir)
	end)
	if not ok then return end
end)

-- the game's own end-of-reel event: true = caught
local fin = RS:FindFirstChild("events") and RS.events:FindFirstChild("bindable_reel_finished")
if fin then
	on(fin.Event, function(caught)
		if not autoOn() then return end
		if caught then
			S.caught += 1
			if S.lastPerfect then S.perfect += 1 end
		else
			S.lost += 1
		end
		S.nextCast = os.clock() + recastDelay() / 1000 + math.random() * 0.25
	end)
end

onFrame(function()
	setStatus(S.status)
	setCaught(tostring(S.caught))
	setPerfect(tostring(S.perfect))
	setLost(tostring(S.lost))
end)

---------------------------------------- freeze: nothing can push you while auto fish runs

-- A rigid AlignPosition pins your root part where you stood (anchoring it breaks the cast: the
-- bobber never lands). Rotation stays free, so water aim can still turn you. Released while
-- swimming, selling or when auto fish / freeze is off.
local FREEZE_STEP = "FischMenuFreeze" .. gui.Name
local hold = {}
local function release()
	if hold.ap then hold.ap:Destroy() end
	if hold.att then hold.att:Destroy() end
	table.clear(hold)
end
RunService:BindToRenderStep(FREEZE_STEP, Enum.RenderPriority.Input.Value + 4, function()
	local char = LP.Character
	local hrp = char and char:FindFirstChild("HumanoidRootPart")
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	local want = hrp and hum and hum.Health > 0 and autoOn() and freezeOn() and not Fisch.busy
		and hum:GetState() ~= Enum.HumanoidStateType.Swimming
	if want then
		if hold.hrp ~= hrp or not (hold.ap and hold.ap.Parent) then
			release()
			hold.hrp = hrp
			hold.att = new("Attachment", { Name = tostring(math.random(1e8, 9e8)), Parent = hrp })
			hold.ap = new("AlignPosition", {
				Mode = Enum.PositionAlignmentMode.OneAttachment, Attachment0 = hold.att, Position = hrp.Position,
				RigidityEnabled = true, MaxForce = math.huge, MaxVelocity = math.huge, Parent = hrp,
			})
		end
	elseif hold.ap then
		release()
	end
end)
Fisch.cleanups[#Fisch.cleanups + 1] = function()
	pcall(RunService.UnbindFromRenderStep, RunService, FREEZE_STEP)
	release()
end

---------------------------------------- cinematic camera: slow orbit while auto fish runs

local CINE_STEP = "FischMenuCine" .. gui.Name
local cine = { on = false }
RunService:BindToRenderStep(CINE_STEP, Enum.RenderPriority.Camera.Value + 1, function(dt)
	local cam = workspace.CurrentCamera
	local char = LP.Character
	local hrp = char and char:FindFirstChild("HumanoidRootPart")
	local active = cam and hrp and autoOn() and cineOn() and not Fisch.busy
	if not active then
		if cine.on and cam then
			cam.CameraType = cine.oldType or Enum.CameraType.Custom
			cine.on = false
		end
		return
	end
	local focus = hrp.Position + Vector3.new(0, 1.6, 0)
	if not cine.on then
		cine.on, cine.oldType, cine.t = true, cam.CameraType, 0
		local off = cam.CFrame.Position - focus
		cine.ang = math.atan2(off.Z, off.X)
		cine.cf = cam.CFrame
	end
	cam.CameraType = Enum.CameraType.Scriptable
	cine.t += dt
	cine.ang += dt * cineSpeed() / 100
	local t = cine.t
	local r = cineDist() * (1 + 0.18 * math.sin(t * 0.21))
	local h = 3 + 2.6 * math.sin(t * 0.33) + r * 0.18
	local eye = focus + Vector3.new(math.cos(cine.ang) * r, h, math.sin(cine.ang) * r)
	local want = CFrame.lookAt(eye, focus + Vector3.new(0, 0.4 * math.sin(t * 0.5), 0))
	cine.cf = cine.cf:Lerp(want, 1 - math.exp(-dt * 2.5))
	cam.CFrame = cine.cf
end)

cleanupFishing = function()
	pcall(RunService.UnbindFromRenderStep, RunService, CINE_STEP)
	if cine.on and workspace.CurrentCamera then workspace.CurrentCamera.CameraType = cine.oldType or Enum.CameraType.Custom end
	alive = false
	pcall(task.cancel, loop)
	pcall(RunService.UnbindFromRenderStep, RunService, REEL_STEP)
	if S.holding then pcall(mouse, false, S.holding) end
	local r = Reel.ActiveReel
	if S.pressedDir and r and r.core and r.core.rod then pcall(setDir, r.core.rod, -1) end
end
end)()

