local rules = Fisch.rules
pcall(function()
	local t = HttpService_:JSONDecode(readfile(RULES_FILE))
	if type(t) == "table" then for k, v in pairs(t) do if type(v) == "number" then rules[k] = v end end end
end)
local function saveRules() pcall(writefile, RULES_FILE, HttpService_:JSONEncode(rules)) end
options["fav.rules"] = {
	save = function() return rules end,
	load = function(t)
		if type(t) ~= "table" then return end
		table.clear(rules)
		for k, v in pairs(t) do if type(v) == "number" then rules[k] = v end end
		saveRules()
	end,
}

-- every catchable fish, rarest first
local order = {}
for i, n in ipairs(R.OrderedRarityNames or {}) do order[n] = i end
local entries = {}
for name, d in pairs(F) do
	if type(d) == "table" and type(name) == "string" and d.Rarity and not d.NonFish and not d.IsCrate then
		entries[#entries + 1] = { name = name, rarity = d.Rarity, icon = d.Icon, ord = order[d.Rarity] or 0, lname = name:lower(), lr = d.Rarity:lower() }
	end
end
table.sort(entries, function(a, b)
	if a.ord ~= b.ord then return a.ord > b.ord end
	return a.name < b.name
end)
local function rarityColor(r)
	local c = R.StaticColors and R.StaticColors[r]
	return typeof(c) == "Color3" and c or C.text
end
local function rarityGrad(r)
	local g = R.GradientColors and R.GradientColors[r]
	if typeof(g) == "ColorSequence" then return g end
	return ColorSequence.new(rarityColor(r))
end

