---------------------------------------- virtual list

local filtered, dirty = {}, true
local function rebuild()
	table.clear(filtered)
	local q = search.Text:lower()
	local head
	for _, e in ipairs(entries) do
		if (q == "" or e.lname:find(q, 1, true) or e.lr:find(q, 1, true)) and (not onlySel or rules[e.name] ~= nil) then
			if not head or head.rarity ~= e.rarity then
				head = { header = true, rarity = e.rarity, n = 0 }
				filtered[#filtered + 1] = head
			end
			head.n += 1
			filtered[#filtered + 1] = e
		end
	end
	list.CanvasSize = UDim2.fromOffset(0, #filtered * ROW_H + 8)
	dirty = true
end

local pool = {}
local function setRule(name, v)
	rules[name] = v
	saveRules()
	if onlySel then rebuild() end
	dirty = true
end
local function makeRow()
	local r = { }
	r.b = button({ Size = UDim2.new(1, -14, 0, ROW_H - 4), Parent = list }, { corner(7) })
	r.st = hoverable(r.b)
	r.ic = new("ImageLabel", { BackgroundTransparency = 1, Position = UDim2.fromOffset(10, 3), Size = UDim2.fromOffset(28, 28), ScaleType = Enum.ScaleType.Fit, Parent = r.b })
	r.nm = label({ Font = Enum.Font.BuilderSansMedium, TextSize = 13, TextColor3 = Color3.new(1, 1, 1), Position = UDim2.fromOffset(48, 0), Size = UDim2.new(1, -250, 1, 0), TextTruncate = Enum.TextTruncate.AtEnd, Parent = r.b })
	r.grad = new("UIGradient", { Parent = r.nm })
	r.nm:SetAttribute("rarity", true) -- fish names never match a menu word, rarity tags must not
	r.rar = label({ TextSize = 11, TextColor3 = C.dim, TextXAlignment = Enum.TextXAlignment.Right, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -128, 0.5, 0), Size = UDim2.fromOffset(100, 20), Parent = r.b })
	r.rar:SetAttribute("rarity", true)
	r.kgF = new("Frame", { BackgroundColor3 = C.field, BorderSizePixel = 0, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -44, 0.5, 0), Size = UDim2.fromOffset(74, 24), Parent = r.b }, { corner(6) })
	r.kgS = stroke(C.fieldStroke, r.kgF)
	r.kg = new("TextBox", {
		Text = "", PlaceholderText = "any", PlaceholderColor3 = C.faint, ClearTextOnFocus = false,
		Font = Enum.Font.BuilderSans, TextSize = 12, TextColor3 = C.hi, TextXAlignment = Enum.TextXAlignment.Right,
		BackgroundTransparency = 1, Position = UDim2.fromOffset(4, 0), Size = UDim2.new(1, -28, 1, 0), Parent = r.kgF,
	})
	label({ Text = "kg", TextSize = 11, TextColor3 = C.faint, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -6, 0, 0), Size = UDim2.fromOffset(16, 24), Parent = r.kgF })
	r.ck = new("Frame", { BackgroundColor3 = C.field, BorderSizePixel = 0, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -12, 0.5, 0), Size = UDim2.fromOffset(18, 18), Parent = r.b }, { corner(5) })
	r.ckS = stroke(C.fieldStroke, r.ck)
	r.ckI = icon(ICON.check, 12, { Position = UDim2.fromScale(0.5, 0.5), ImageColor3 = Color3.new(1, 1, 1), Parent = r.ck })
	-- header look
	r.hd = label({ Font = Enum.Font.BuilderSansBold, TextSize = 11, TextColor3 = Color3.new(1, 1, 1), Position = UDim2.fromOffset(12, 0), Size = UDim2.new(0.5, 0, 1, 0), Parent = r.b })
	r.hdGrad = new("UIGradient", { Parent = r.hd })
	r.hd:SetAttribute("rarity", true)
	r.hdN = label({ TextSize = 11, TextColor3 = C.faint, TextXAlignment = Enum.TextXAlignment.Right, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -12, 0, 0), Size = UDim2.fromOffset(120, ROW_H - 4), Parent = r.b })
	r.hdLine = new("Frame", { BorderSizePixel = 0, BackgroundTransparency = 0.7, Position = UDim2.new(0, 12, 1, -2), Size = UDim2.new(1, -24, 0, 1), Parent = r.b })
	on(r.b.Activated, function()
		local e = r.item
		if not e or e.header then return end
		if rules[e.name] ~= nil then setRule(e.name, nil) else setRule(e.name, 0) end
	end)
	on(r.kg.FocusLost, function()
		local e = r.item
		if not e or e.header then return end
		local n = tonumber((r.kg.Text:gsub(",", ".")))
		if n and n > 0 then
			setRule(e.name, n)
			r.kg.Text = tostring(n)
		else
			r.kg.Text = ""
			if rules[e.name] ~= nil then setRule(e.name, 0) end
		end
	end)
	return r
end
local function fill(r, e)
	r.item = e
	local hdr = e.header == true
	for _, k in ipairs({ "ic", "nm", "rar", "kgF", "ck" }) do r[k].Visible = not hdr end
	r.hd.Visible, r.hdN.Visible, r.hdLine.Visible = hdr, hdr, hdr
	if hdr then
		r.hd.Text = e.rarity:upper()
		r.hdGrad.Color = rarityGrad(e.rarity)
		r.hdLine.BackgroundColor3 = rarityColor(e.rarity)
		r.hdN.Text = e.n .. " fish"
	else
		r.ic.Image = e.icon or ""
		r.nm.Text = e.name
		r.grad.Color = rarityGrad(e.rarity)
		r.rar.Text = e.rarity
		local v = rules[e.name]
		if not r.kg:IsFocused() then r.kg.Text = (v and v > 0) and tostring(v) or "" end
	end
end

local lastY, lastH = -1, -1
onFrame(function()
	if not page.Visible then return end
	holderF.Size = UDim2.new(1, -28, 0, math.max(page.AbsoluteSize.Y / C.S() - 20, 200))
	-- header pills, switch, counters
	for i, p in ipairs(pills) do
		local sel = (i == 2) == onlySel
		p.b.BackgroundColor3 = C.field:Lerp(C.fieldHover, p.st.hover.x)
		p.b.BackgroundTransparency = sel and 0 or 0.6
		p.l.TextColor3 = sel and C.hi or C.dim
	end
	local nSel = 0
	for _ in pairs(rules) do nSel += 1 end
	local t = #entries .. " fish  ·  " .. nSel .. " selected"
	C.setText(countLbl, t)

	local y, h = list.CanvasPosition.Y, list.AbsoluteSize.Y / C.S()
	if dirty or y ~= lastY or h ~= lastH then
		dirty, lastY, lastH = false, y, h
		local first = math.floor(y / ROW_H) + 1
		local need = math.ceil(h / ROW_H) + 2
		while #pool < need do pool[#pool + 1] = makeRow() end
		for i, r in ipairs(pool) do
			local idx = first + i - 1
			local e = filtered[idx]
			if e and i <= need then
				r.b.Visible = true
				r.b.Position = UDim2.fromOffset(6, (idx - 1) * ROW_H + 4)
				if r.item ~= e or r.stale ~= rules[e.name] then
					fill(r, e)
					r.stale = rules[e.name]
				end
			else
				r.b.Visible = false
				r.item = nil
			end
		end
	end
	-- live visuals of visible rows
	for _, r in ipairs(pool) do
		local e = r.item
		if r.b.Visible and e and not e.header then
			local sel = rules[e.name] ~= nil
			r.b.BackgroundTransparency = 1 - math.max(0.035 * r.st.hover.x, sel and 0.045 or 0)
			r.ck.BackgroundColor3 = sel and accent or C.field
			r.ckS.Color = sel and accent or C.fieldStroke:Lerp(C.dim, r.st.hover.x * 0.5)
			r.ckI.ImageTransparency = sel and 0 or 1
			r.kgF.BackgroundTransparency = sel and 0 or 0.5
		elseif r.b.Visible then
			r.b.BackgroundTransparency = 1
		end
	end
end)
on(search:GetPropertyChangedSignal("Text"), rebuild)
for i, p in ipairs(pills) do on(p.b.Activated, function() onlySel = i == 2; rebuild(); list.CanvasPosition = Vector2.zero end) end
rebuild()

