-- LinearVelocity holds the exact velocity (no gravity sag, nothing pulls back); the humanoid is
-- platform-stood so its own walking forces can't fight it.
local function setup(char, hrp, hum)
	fly.char, fly.hum = char, hum
	fly.att = new("Attachment", { Name = tostring(math.random(1e8, 9e8)), Parent = hrp })
	fly.lv = new("LinearVelocity", {
		Attachment0 = fly.att, MaxForce = math.huge, VelocityConstraintMode = Enum.VelocityConstraintMode.Vector,
		RelativeTo = Enum.ActuatorRelativeTo.World, VectorVelocity = Vector3.zero, Parent = hrp,
	})
	fly.ao = new("AlignOrientation", {
		Mode = Enum.OrientationAlignmentMode.OneAttachment, Attachment0 = fly.att, MaxTorque = math.huge,
		Responsiveness = 60, CFrame = hrp.CFrame.Rotation, Parent = hrp,
	})
	hum.PlatformStand = true
end
RunService:BindToRenderStep(FLY_STEP, Enum.RenderPriority.Input.Value + 2, function()
	local char = LP.Character
	local hrp = char and char:FindFirstChild("HumanoidRootPart")
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	if not (flyOn() and hrp and hum and hum.Health > 0) then
		if fly.lv then teardown() end
		return
