	if fly.char ~= char or not (fly.lv and fly.lv.Parent) then teardown(); setup(char, hrp, hum) end
	hum.PlatformStand = true
	local cam = workspace.CurrentCamera
	local cf = cam.CFrame
	local move = Vector3.zero
	if not UIS:GetFocusedTextBox() then
		local K = Enum.KeyCode
		if UIS:IsKeyDown(K.W) then move += cf.LookVector end
		if UIS:IsKeyDown(K.S) then move -= cf.LookVector end
		if UIS:IsKeyDown(K.D) then move += cf.RightVector end
		if UIS:IsKeyDown(K.A) then move -= cf.RightVector end
		if UIS:IsKeyDown(K.Space) then move += Vector3.yAxis end
		if UIS:IsKeyDown(K.LeftControl) then move -= Vector3.yAxis end
	end
	fly.lv.VectorVelocity = move.Magnitude > 0 and move.Unit * flySpeed() or Vector3.zero
	local flat = Vector3.new(cf.LookVector.X, 0, cf.LookVector.Z)
