---------------------------------------------------- FL network: who runs the script, badges, cloud configs

;(function()
local BRIDGE = "https://fl-bridge.utochka4515.workers.dev"
local HttpService_ = game:GetService("HttpService")
local Players_ = game:GetService("Players")
local TCS = game:GetService("TextChatService")
local CoreGui_ = game:GetService("CoreGui")
local req = request or (http and http.request) or (syn and syn.request)

local function call(method, path, body)
	if not req then return nil, "no http" end
	local ok, res = pcall(req, {
		Url = BRIDGE .. path, Method = method,
		Headers = { ["Content-Type"] = "application/json" }, Body = body,
	})
	if not ok or type(res) ~= "table" then return nil, "network" end
	if (res.StatusCode or 0) >= 400 then
		local ok2, e = pcall(HttpService_.JSONDecode, HttpService_, res.Body or "")
		return nil, ok2 and type(e) == "table" and e.error or ("http " .. tostring(res.StatusCode))
	end
	local ok3, data = pcall(HttpService_.JSONDecode, HttpService_, res.Body or "")
	return ok3 and data or res.Body
end

local net = { users = {} } -- userId (string) -> name, everyone on this server running the script
Fisch.net = net
local ng = settingsSafety
local badgesOn = toggleControl(ng, "net.badges", "Synchronization", true)
local ICON_FL = ICON.fl

---------------------------------------- presence (every 5 s) + incoming config offers

local function isUser(p) return p and net.users[tostring(p.UserId)] ~= nil end
local offerHandler
task.spawn(function()
	while gui.Parent do
		if game.JobId ~= "" then
			local data = call("POST", "/presence", HttpService_:JSONEncode({ u = tostring(LP.UserId), n = LP.Name, j = game.JobId }))
			if type(data) == "table" then
				local users = {}
				for _, u in ipairs(data.users or {}) do users[tostring(u.u)] = u.n end
				net.users = users
				for _, o in ipairs(data.offers or {}) do
					if offerHandler then task.spawn(offerHandler, o) end
				end
			end
		end
		task.wait(5)
	end
end)

---------------------------------------- badges: player list, Roblox people panel, nametag, chat

local function badge(parent, size)
	local b = parent:FindFirstChild("FLBadge")
	if not b then
		b = new("ImageLabel", { Name = "FLBadge", BackgroundTransparency = 1, Image = ICON_FL, ScaleType = Enum.ScaleType.Fit, Parent = parent }, { corner(3) })
	end
	b.Size = UDim2.fromOffset(size, size)
	return b
end
local function clear(parent)
	local b = parent and parent:FindFirstChild("FLBadge")
	if b then b:Destroy() end
end

-- the game's own player list: PlayerGui.PlayerList.Panel.List.<Name>.NameFrame.Name (horizontal list)
local function playerList()
	local pg = LP:FindFirstChild("PlayerGui")
	local list = pg and pg:FindFirstChild("PlayerList")
	list = list and list:FindFirstChild("Panel")
	list = list and list:FindFirstChild("List")
	if not list then return end
	for _, p in ipairs(Players_:GetPlayers()) do
		local row = list:FindFirstChild(p.Name)
		local holder = row and row:FindFirstChild("NameFrame")
		holder = holder and holder:FindFirstChild("Name")
		if holder then
			if badgesOn() and isUser(p) then
				local b = badge(holder, 18)
				b.LayoutOrder = -1
			else
				clear(holder)
			end
		end
	end
end

-- Roblox's own people panel (top bar menu): labels showing a user's display name
local function peoplePanel()
	local names = {}
	for _, p in ipairs(Players_:GetPlayers()) do
		if badgesOn() and isUser(p) then names[p.DisplayName] = true; names["@" .. p.Name] = true end
	end
	for _, d in ipairs(CoreGui_:GetDescendants()) do
		if d:IsA("TextLabel") and d:IsDescendantOf(gui) then
			local own = d:FindFirstChild("FLBadge")
			if own then own:Destroy() end
		elseif d:IsA("TextLabel") and d.Visible then
			local want = names[d.Text] == true
			local has = d:FindFirstChild("FLBadge")
			if want and not has then
				local s = math.clamp(d.TextSize + 2, 14, 20)
				local b = badge(d, s)
				b.AnchorPoint = Vector2.new(1, 0.5)
				b.Position = UDim2.new(0, -5, 0.5, 0)
			elseif has and not want then
				has:Destroy()
			end
		end
	end
end

-- over the head: next to the name in the game's "user" billboard, or a small billboard of our own
local tags = {}
local function nametags()
	for _, p in ipairs(Players_:GetPlayers()) do
		local char = p.Character
		local hrp = char and char:FindFirstChild("HumanoidRootPart")
		local bb = hrp and hrp:FindFirstChild("user")
		local nameLbl = bb and bb:FindFirstChild("user")
		local on_ = badgesOn() and isUser(p) and hrp ~= nil
		if on_ and nameLbl and nameLbl:IsA("TextLabel") then
			if tags[p] then tags[p]:Destroy(); tags[p] = nil end
			local s = math.max(10, math.floor(nameLbl.AbsoluteSize.Y * 0.9))
			local b = badge(nameLbl, s)
			local tb = nameLbl.TextBounds
			local x = (nameLbl.AbsoluteSize.X - tb.X) / 2 - s - 4
			b.Position = UDim2.fromOffset(math.floor(x), math.floor((nameLbl.AbsoluteSize.Y - s) / 2))
		elseif on_ then
			if not (tags[p] and tags[p].Parent) then
				tags[p] = new("BillboardGui", {
					Name = "FLBadge", Size = UDim2.fromOffset(22, 22), StudsOffset = Vector3.new(0, 4.2, 0),
					AlwaysOnTop = true, LightInfluence = 0, MaxDistance = 120, Adornee = hrp, Parent = gui,
				}, { new("ImageLabel", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Image = ICON_FL }, { corner(4) }) })
			end
			tags[p].Adornee = hrp
		else
			if nameLbl then clear(nameLbl) end
			if tags[p] then tags[p]:Destroy(); tags[p] = nil end
		end
	end
	for p, t in pairs(tags) do if not p.Parent then t:Destroy(); tags[p] = nil end end
end

-- chat: rich text can't hold images, so the prefix starts with a reserved gap and the badge image is
-- laid over that gap in the chat window
local GAP = "\u{2003}\u{2002}"
local prevCb
pcall(function() prevCb = getcallbackvalue(TCS, "OnIncomingMessage") end)
local function onIncoming(msg)
	local props = prevCb and prevCb(msg)
	local src = msg.TextSource
	if badgesOn() and ((src and net.users[tostring(src.UserId)]) or msg.Metadata == "fl-badge-test") then
		props = props or Instance.new("TextChatMessageProperties")
		props.PrefixText = GAP .. ((props.PrefixText ~= nil and props.PrefixText ~= "") and props.PrefixText or msg.PrefixText)
	end
	return props
end
TCS.OnIncomingMessage = onIncoming
local function chatLabel(d)
	if not (d:IsA("TextLabel") and d.Text:sub(1, #GAP) == GAP) then return end
	local s = math.clamp(d.TextSize + 1, 13, 22)
	local b = badge(d, s)
	b.Position = UDim2.fromOffset(0, math.max(0, math.floor((d.TextSize - s) / 2) + 1))
end
local chatConn
local function hookChat()
	local ec = CoreGui_:FindFirstChild("ExperienceChat")
	if not ec or chatConn then return end
	for _, d in ipairs(ec:GetDescendants()) do pcall(chatLabel, d) end
	chatConn = ec.DescendantAdded:Connect(function(d)
		task.defer(function()
			pcall(chatLabel, d)
			if d:IsA("TextLabel") then
				d:GetPropertyChangedSignal("Text"):Once(function() pcall(chatLabel, d) end)
			end
		end)
	end)
end

task.spawn(function()
	local n = 0
	while gui.Parent do
		pcall(playerList)
		pcall(hookChat)
		n += 1
		if n % 2 == 0 then pcall(peoplePanel) end
		task.wait(1)
	end
end)
RunService:BindToRenderStep("FischMenuTags" .. gui.Name, Enum.RenderPriority.Last.Value, function() pcall(nametags) end)

---------------------------------------- pets: a little FL cube floats next to every other script user

-- Only other players get one on your screen (yours shows on theirs, since they run the script too).
local petFolder = new("Folder", { Name = tostring(math.random(1e8, 9e8)), Parent = workspace })
local pets = {}
local function makePet()
	local p = new("Part", {
		Size = Vector3.new(1.15, 1.15, 1.15), Anchored = true, CanCollide = false, CanQuery = false, CanTouch = false,
		CastShadow = false, Material = Enum.Material.SmoothPlastic, Color = Color3.fromRGB(11, 17, 27), Parent = petFolder,
	})
	for _, face in ipairs({ Enum.NormalId.Front, Enum.NormalId.Back, Enum.NormalId.Left, Enum.NormalId.Right, Enum.NormalId.Top }) do
		new("Decal", { Texture = ICON_FL, Face = face, Parent = p })
	end
	return { part = p, t = math.random() * 10 }
end
local PET_STEP = "FischMenuPets" .. gui.Name
RunService:BindToRenderStep(PET_STEP, Enum.RenderPriority.Last.Value, function(dt)
	for _, pl in ipairs(Players_:GetPlayers()) do
		local char = pl.Character
		local hrp = char and char:FindFirstChild("HumanoidRootPart")
		local want = hrp and badgesOn() and isUser(pl) and (pl ~= LP or Fisch.petSelfTest)
		local pet = pets[pl]
		if want then
			if not (pet and pet.part.Parent) then pet = makePet(); pets[pl] = pet end
			pet.t += dt
			local t = pet.t
			local goal = hrp.CFrame * CFrame.new(2.4, 1.1 + math.sin(t * 2.2) * 0.3, 1.6)
			local pos = pet.pos and pet.pos:Lerp(goal.Position, 1 - math.exp(-dt * 7)) or goal.Position
			pet.pos = pos
			local look = hrp.CFrame.LookVector
			pet.part.CFrame = CFrame.lookAt(pos, pos + Vector3.new(look.X, 0, look.Z)) * CFrame.Angles(math.sin(t * 1.6) * 0.12, 0, math.sin(t * 1.3) * 0.1)
		elseif pet then
			pet.part:Destroy()
			pets[pl] = nil
		end
	end
	for pl, pet in pairs(pets) do if not pl.Parent then pet.part:Destroy(); pets[pl] = nil end end
end)

Fisch.cleanups[#Fisch.cleanups + 1] = function()
	pcall(RunService.UnbindFromRenderStep, RunService, PET_STEP)
	petFolder:Destroy()
	pcall(RunService.UnbindFromRenderStep, RunService, "FischMenuTags" .. gui.Name)
	pcall(function() TCS.OnIncomingMessage = prevCb end)
	if chatConn then chatConn:Disconnect() end
	for _, t in pairs(tags) do pcall(t.Destroy, t) end
	pcall(function()
		for _, root in ipairs({ LP.PlayerGui, CoreGui_, workspace }) do
			for _, d in ipairs(root:GetDescendants()) do
				if d.Name == "FLBadge" and d:IsA("ImageLabel") then d:Destroy() end
			end
		end
	end)
end

---------------------------------------- cloud configs

local function upload(data)
	local res, err = call("POST", "/cfg", data)
	if type(res) == "table" and res.code then return res.code end
	return nil, err
end
local function download(code)
	local res, err = call("GET", "/cfg/" .. code:upper():gsub("[^%w]", ""))
	if type(res) == "table" then return HttpService_:JSONEncode(res) end
	return nil, err
end
-- saves a downloaded config as a new local config and loads it
local function adopt(data, base)
	local name = uniqueName(DIR_CFG, base)
	writefile(cfgPath(DIR_CFG, name), data)
	Configs.load(name)
	return name
end

-- Share in a config's menu: upload it, put the short code in the clipboard
function Configs.share(name)
	local ok, data = pcall(readfile, cfgPath(DIR_CFG, name))
	if not ok then return end
	task.spawn(function()
		local code, err = upload(data)
		if code then
			if setclipboard then pcall(setclipboard, code) end
			toast("Code " .. code .. " copied")
		else
			toast("Upload failed: " .. tostring(err))
		end
	end)
end

-- Send to player in a config's menu: pick a script user on this server
function Configs.sendTo(name, anchor)
	local items = {}
	for uid, uname in pairs(net.users) do
		if uid ~= tostring(LP.UserId) then
			local p = Players_:GetPlayerByUserId(tonumber(uid))
			local shown = p and p.DisplayName or uname
			items[#items + 1] = { icon = ICON.person, text = shown, fn = function()
				task.spawn(function()
					local ok, data = pcall(readfile, cfgPath(DIR_CFG, name))
					if not ok then return end
					local code, err = upload(data)
					if not code then toast("Upload failed: " .. tostring(err)) return end
					local r, e = call("POST", "/offer", HttpService_:JSONEncode({ from = tostring(LP.UserId), fromName = LP.DisplayName, to = uid, code = code }))
					toast(r and ("Sent to " .. shown) or ("Send failed: " .. tostring(e)))
				end)
			end }
		end
	end
	if #items == 0 then items[1] = { icon = ICON.person, text = "No FL users on this server", disabled = true, fn = function() end } end
	contextAtMouse(items, anchor)
end

-- an incoming offer: 10 s card with Accept / Decline
offerHandler = function(o)
	local who = o.fromName ~= "" and o.fromName or ("user " .. tostring(o.from))
	Fisch.notify(who .. " sent you a config", "Code " .. tostring(o.code), "Accept", function()
		local data, err = download(o.code)
		if data then
			adopt(data, "from " .. who)
			toast("Config loaded")
		else
			toast("Code not found")
		end
	end, 10, "Decline", function() end)
end

-- load by code: the cloud button next to the config bar in the header
Fisch.loadCode = function(code)
	code = tostring(code or ""):upper():gsub("[^%w]", "")
	if #code < 4 then toast("Enter a code") return end
	local data = download(code)
	if data then
		adopt(data, "cloud " .. code)
		toast("Config loaded")
	else
		toast("Code not found")
	end
end
end)()

