local tip = new("Frame", {
	BackgroundColor3 = C.popup, BorderSizePixel = 0, Size = UDim2.fromOffset(260, 0), AutomaticSize = Enum.AutomaticSize.Y,
	Visible = false, ZIndex = 300, Parent = gui,
}, {
	corner(8),
	new("UIPadding", { PaddingTop = UDim.new(0, 9), PaddingBottom = UDim.new(0, 10), PaddingLeft = UDim.new(0, 12), PaddingRight = UDim.new(0, 12) }),
	new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 5) }),
})
stroke(C.popupStroke, tip)
local tTitle = new("TextLabel", { BackgroundTransparency = 1, Font = Enum.Font.BuilderSansMedium, TextSize = 13, TextColor3 = C.hi, TextXAlignment = Enum.TextXAlignment.Left, Size = UDim2.new(1, 0, 0, 16), LayoutOrder = 1, ZIndex = 301 })
local tDesc = new("TextLabel", { BackgroundTransparency = 1, Font = Enum.Font.BuilderSans, TextSize = 12, TextColor3 = C.text, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, ZIndex = 301 })
local tVal = new("TextLabel", { BackgroundTransparency = 1, Font = Enum.Font.BuilderSans, TextSize = 11, TextColor3 = C.dim, TextXAlignment = Enum.TextXAlignment.Left, Size = UDim2.new(1, 0, 0, 14), LayoutOrder = 3, ZIndex = 301 })
-- the tooltip writes its own language: keep the translation layer off it
for _, o in ipairs({ tTitle, tDesc, tVal }) do
	C.src[o] = false
	o.Parent = tip
end

local function shown(g)
	local o = g
	while o and o ~= gui do
		if o:IsA("GuiObject") and not o.Visible then return false end
		o = o.Parent
	end
	return o == gui
end
local hov, since = nil, 0
local lastLang
local last = os.clock()
onFrame(function()
	local now = os.clock()
	local dt = now - last
	last = now
	local ru = lang() == "Русский"
	if ru ~= lastLang then
		lastLang, isRu = ru, ru
		applyAll()
	end
	local found
	if infoOn() and holder.Visible then
		local m = mouseAbs()
		for r, text in pairs(C.rows) do
			if D[text] and r.Parent and inside(r, m) and shown(r) then found = r break end
		end
	end
	if found ~= hov then hov, since = found, 0 end
	since += dt
	if not (hov and since >= 1) then
		tip.Visible = false
		return
	end
	local key = C.rows[hov]
	local d = D[key]
	local title = ru and translate(key) or key
	C.setText(tTitle, title)
	local desc = ru and d[2] or d[1]
	C.setText(tDesc, desc)
	local vals = ru and d[4] or d[3]
	local v = vals ~= "" and ((ru and "Значения: " or "Values: ") .. vals) or ""
	C.setText(tVal, v)
	tVal.Visible = v ~= ""
	local p = mouseAbs() - probe.AbsolutePosition
	local vp = gui.AbsoluteSize
	local x = math.min(p.X + 16, vp.X - 270)
	local y = math.min(p.Y + 18, vp.Y - tip.AbsoluteSize.Y - 8)
	tip.Position = UDim2.fromOffset(round(x), round(y))
	tip.Visible = true
end)
end)()


-- api.Destroy disconnects `on` connections before destroying the gui, so this one is plain
gui.Destroying:Connect(function()
	pcall(cleanupFishing)
	for _, f in ipairs(Fisch.cleanups) do pcall(f) end
end)

end)()

inject()

---------------------------------------------------------------- window state & input

-- own function: Luau allows 200 registers per function and the main chunk is full
return (function()

local cam = workspace.CurrentCamera
local vp = cam.ViewportSize
local px = spring(round((vp.X - START_SIZE.X) / 2), 24, 0.01)
local py = spring(round((vp.Y - START_SIZE.Y) / 2), 24, 0.01)
local sw = spring(START_SIZE.X, 26, 0.01)
local sh = spring(START_SIZE.Y, 26, 0.01)
local scale = spring(1, 24, 1e-4)
local alpha = spring(1, 22, 1e-4)
local tilt = spring(0, 16, 1e-3)

local open = false
local dragging, resizing = false, false
local dragOffset, resizeAnchor, resizeStart

local function setOpen(state)
	if state == nil then state = not open end
	open = state
	alpha.t = open and 0 or 1
	if not open then
		dragging, resizing, pickDrag, listeningBind = false, false, nil, nil
		hideAllPopups()
		local focused = UIS:GetFocusedTextBox()
		if focused and focused:IsDescendantOf(gui) then focused:ReleaseFocus() end
	end
	modal.Visible, modal.Modal = open, open
end

-- First person (CameraMode LockFirstPerson) locks and hides the system cursor, and the game also
-- forces LockCenter every frame. While open: a Modal button in a plain ScreenGui (one inside a
-- CanvasGroup doesn't count), MouseBehavior forced to Default last in the frame, and our own
-- arrow drawn at the mouse, since the system cursor stays hidden in first person.
local cursorGui = new("ScreenGui", {
	Name = tostring(math.random(1e8, 9e8)),
	ResetOnSpawn = false,
	IgnoreGuiInset = true,
	DisplayOrder = 10001,
})
if syn and syn.protect_gui then pcall(syn.protect_gui, cursorGui) end
cursorGui.Parent = gui.Parent
local modalBtn = new("TextButton", { Text = "", Modal = true, BackgroundTransparency = 1, Size = UDim2.fromOffset(1, 1), Visible = false, Parent = cursorGui })
local cursorImg = new("ImageLabel", { Image = ICON.cursor, BackgroundTransparency = 1, Size = UDim2.fromOffset(24, 24), Visible = false, Parent = cursorGui })

local CURSOR_STEP = "FischMenuCursor" .. gui.Name
local LocalPlayer = game:GetService("Players").LocalPlayer
local savedIcon, savedBehavior
-- While open, the game's own writes to MouseBehavior / MouseIconEnabled are parked here and
-- applied on close, so whatever the game wanted in the meantime (spawn, emote, spectate) sticks.
local parking = false
if hookmetamethod and checkcaller then
	local realUIS = UIS
	local oldNewindex
	oldNewindex = hookmetamethod(game, "__newindex", function(self, k, v)
		if parking and self == realUIS and (k == "MouseBehavior" or k == "MouseIconEnabled") and not checkcaller() then
			-- LockCurrentPosition is the camera's right-mouse pan state, not where it wants to end up
			if k == "MouseIconEnabled" then savedIcon = v
			elseif v ~= Enum.MouseBehavior.LockCurrentPosition then savedBehavior = v end
			return
		end
		return oldNewindex(self, k, v)
	end)
end
local function firstPerson()
	if LocalPlayer.CameraMode == Enum.CameraMode.LockFirstPerson then return true end
	local c = workspace.CurrentCamera
	return c ~= nil and (c.CFrame.Position - c.Focus.Position).Magnitude < 0.75
end
RunService:BindToRenderStep(CURSOR_STEP, Enum.RenderPriority.Last.Value + 1000, function()
	if open then
		if savedIcon == nil then
			savedIcon, savedBehavior = UIS.MouseIconEnabled, UIS.MouseBehavior
			if savedBehavior ~= Enum.MouseBehavior.Default and not firstPerson() then savedBehavior = Enum.MouseBehavior.Default end
			if not firstPerson() then savedIcon = true end
		end
		parking = true
		-- first person keeps the system cursor hidden, so ours is drawn there; elsewhere the real one has no lag
		local fp = firstPerson()
		if UIS.MouseBehavior ~= Enum.MouseBehavior.Default then UIS.MouseBehavior = Enum.MouseBehavior.Default end
		if UIS.MouseIconEnabled == fp then UIS.MouseIconEnabled = not fp end
		modalBtn.Visible, modalBtn.Modal = true, true
		cursorImg.Visible = fp
		if fp then
			local m = UIS:GetMouseLocation()
			cursorImg.Position = UDim2.fromOffset(round(m.X) - 4, round(m.Y) - 2)
		end
	elseif savedIcon ~= nil then
		parking = false
		-- Modal off first: a Modal button left on keeps the mouse free and the camera dead
		modalBtn.Modal, modalBtn.Visible = false, false
		cursorImg.Visible = false
		-- a pan that ended while the menu was open would leave the camera dead: a hidden cursor means
		-- the game plays with the mouse locked to the center
		if savedBehavior == Enum.MouseBehavior.LockCurrentPosition and not UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) then
			savedBehavior = savedIcon == false and Enum.MouseBehavior.LockCenter or Enum.MouseBehavior.Default
		end
		UIS.MouseIconEnabled, UIS.MouseBehavior = savedIcon, savedBehavior
		savedIcon, savedBehavior = nil, nil
	end
end)

local function isPress(input)
	return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
end

-- Hover flags can go stale when a popup hides under a still cursor; only trust visible hits.
local function isShown(g)
	while g and g ~= gui do
		if g:IsA("GuiObject") and not g.Visible then return false end
		g = g.Parent
	end
	return g == gui
end
local function overControl(m)
	for g in pairs(hovered) do
		if g.Parent and inside(g, m) and isShown(g) then return true end
	end
	return false
end

local function beginDrag(input)
	if not open or not isPress(input) then return end
	local m = mouseAbs()
	if overControl(m) or popupAt(m) then return end
	dragging = true
	-- Grab relative to where the window is drawn now, so it never jumps under the cursor.
	dragOffset = UIS:GetMouseLocation() - Vector2.new(px.x, py.x)
end
on(topbar.InputBegan, beginDrag)
on(sidebar.InputBegan, beginDrag)

on(closeBtn.Activated, function()
	if window:GetAttribute("Overlay") then
		window:SetAttribute("Overlay", false)
		return
	end
	setOpen(false)
end)
on(grip.MouseButton1Down, function()
	if popupAt(mouseAbs()) then return end
	resizing = true
	resizeAnchor = UIS:GetMouseLocation()
	resizeStart = Vector2.new(sw.t, sh.t)
end)

on(UIS.InputBegan, function(input)
	if listeningBind then
		local t = input.UserInputType
		if t == Enum.UserInputType.MouseButton1 or t == Enum.UserInputType.MouseButton2 or t == Enum.UserInputType.MouseButton3 then
			listeningBind.capture({ kind = "Mouse", name = t.Name })
		elseif input.KeyCode ~= Enum.KeyCode.Unknown then
			listeningBind.capture({ kind = "Key", name = input.KeyCode.Name })
		end
		return
	end
	if open and (isPress(input) or input.UserInputType == Enum.UserInputType.MouseButton2) then
		closePopupsOutside(mouseAbs())
	end
	if UIS:GetFocusedTextBox() then return end
	hotkeyInput(input, true)
	if matchesKey(input, menuKey) then setOpen() end
end)

on(UIS.InputEnded, function(input)
	hotkeyInput(input, false)
	if isPress(input) then
		dragging, resizing, pickDrag = false, false, nil
		for s in pairs(pressSprings) do s.t = 0 end
	end
end)

local function wheelTarget()
	if not open or not hoveredWheel then return nil end
	local m = mouseAbs()
	if not (inside(hoveredWheel, m) and isShown(hoveredWheel)) then return nil end
	local top = popupAt(m)
	if top and not hoveredWheel:IsDescendantOf(top.inner) then return nil end
	return wheelTargets[hoveredWheel]
end

on(UIS.InputChanged, function(input)
	if input.UserInputType ~= Enum.UserInputType.MouseWheel then return end
	local fn = wheelTarget()
	if fn then
		local d = input.Position.Z > 0 and 1 or -1
		fn(shiftDown() and d * 10 or d, shiftDown())
	end
end)

local MOUSE_SINK = "FischMenuMouse" .. gui.Name
local mouseSinking = false
local function setMouseSink(want)
	if want == mouseSinking then return end
	mouseSinking = want
	if want then
		CAS:BindActionAtPriority(MOUSE_SINK, function() return Enum.ContextActionResult.Sink end, false, 100000,
			Enum.UserInputType.MouseButton1, Enum.UserInputType.MouseButton2, Enum.UserInputType.MouseButton3, Enum.UserInputType.MouseWheel)
	else
		CAS:UnbindAction(MOUSE_SINK)
	end
end

-- Keep the camera from zooming while the wheel is adjusting a value.
local SINK = "FischMenuWheel" .. gui.Name
local sinking = false
local function setSink(want)
	if want == sinking then return end
	sinking = want
	if want then
		CAS:BindActionAtPriority(SINK, function() return Enum.ContextActionResult.Sink end, false, 10000, Enum.UserInputType.MouseWheel)
	else
		CAS:UnbindAction(SINK)
	end
end

on(RunService.RenderStepped, function(dt)
	dt = math.min(dt, 1 / 20)
	local m = UIS:GetMouseLocation()
	vp = cam.ViewportSize

	if dragging then
		local p = m - dragOffset
		px.t = math.clamp(p.X, 80 - sw.t, vp.X - 80)
		py.t = math.clamp(p.Y, 0, vp.Y - HEADER_H)
	end
	if resizing then
		local d = m - resizeAnchor
		sw.t = math.clamp(resizeStart.X + d.X / C.S(), MIN_SIZE.X, vp.X)
		sh.t = math.clamp(resizeStart.Y + d.Y / C.S(), MIN_SIZE.Y, vp.Y)
	end

	scale.t = 1
	for s in pairs(springs) do s:step(dt) end

	-- Whole pixels and even sizes keep the centered canvas on the pixel grid at rest.
	local w, h = even(sw.x), even(sh.x)
	holder.Size = UDim2.fromOffset(w + 2 * PAD, h + 2 * PAD)
	holder.Position = UDim2.fromOffset(round(px.x) + w / 2, round(py.x) + h / 2 + round(alpha.x * 8)) -- slides in by whole pixels
	holder.Rotation = math.abs(tilt.x) < 0.01 and 0 or tilt.x
	holderScale.Scale = scale.x * (C.dpi or 1)
	holder.GroupTransparency = alpha.x
	holder.Visible = open or alpha.x < 0.995
	setBlur(holder.Visible and (1 - alpha.x) or 0)

	-- the menu color's alpha fades the accent into the background
	local dc = C.window:Lerp(menuColor:display(), menuColor.da.x)
	if dc ~= accent then setAccent(dc) end

	closeBtn.BackgroundTransparency = 1 - closeSt.hover.x
	closeScale.Scale = 1 - closeSt.press.x * 0.12
	local lc = C.dim:Lerp(C.hi, closeSt.hover.x)
	for _, l in ipairs(closeLines) do l.BackgroundColor3 = lc end
	local gc = C.dim:Lerp(C.text, math.max(gripSt.hover.x, resizing and 1 or 0))
	for _, d in ipairs(gripDots) do d.BackgroundColor3 = gc end

	local shown = holder.Visible
	for fn in pairs(frameFns) do
		if (shown or C.always[fn]) and fn(dt) == true then frameFns[fn] = nil end
	end

	setSink(wheelTarget() ~= nil)
	setMouseSink(open and (dragging or resizing or inside(window, mouseAbs())))
end)

---------------------------------------------------------------- startup

do
	local ok, st = pcall(function() return HttpService:JSONDecode(readfile(STATE_FILE)) end)
	if ok and type(st) == "table" and type(st.config) == "string" and st.config ~= "" and isfile(cfgPath(DIR_CFG, st.config)) then
		local ok2, data = pcall(readfile, cfgPath(DIR_CFG, st.config))
		if ok2 and applyConfig(data) then selected = st.config end
	end
	-- loading snaps straight to the saved color instead of animating from the default
	menuColor:set(menuColor.h, menuColor.s, menuColor.v, menuColor.a, true)
	refreshConfigs()
end

local api = {}
api.Gui, api.Pages, api.Toggle, api.Configs = gui, pages, setOpen, Configs
function api.Move(x, y)
	px:snap(x)
	py:snap(y)
end
function api.Option(id, v) -- set any saved option from outside (testing)
	local o = options[id]
	if o then o.load(v) end
	return o and o.save()
end
function api.Set(id, v) -- flip a toggle from outside (testing)
	local r = functions[id]
	if r then r.set(v) end
	return r and r.get()
end
function api.Select(name)
	for _, tab in ipairs(tabs) do
		if tab.name == name then selectTab(tab) end
	end
end
function api.Destroy()
	RunService:UnbindFromRenderStep(GLASS_STEP)
	RunService:UnbindFromRenderStep(CURSOR_STEP)
	parking = false
	cursorGui:Destroy()
	if savedIcon ~= nil then UIS.MouseIconEnabled, UIS.MouseBehavior = savedIcon, savedBehavior end
	setSink(false)
	setMouseSink(false)
	setBlur(0)
	blurDof:Destroy()
	glass:Destroy()
	for _, c in ipairs(conns) do c:Disconnect() end
	gui:Destroy()
	if env.__FischMenu == api then env.__FischMenu = nil end
end
env.__FischMenu = api

selectTab(tabs[1], true)
setOpen(true)
inject(true)
return "ok"
end)()
